#define SC_HEIGHT         480
#define SC_SIZEIMAGE      (160 * 1024)
#define SC_NBUFFERS       2
#define SC_CAPTURE_TMO_MS 5000
```

完整函数体（第271-404行）：
```c
static ssize_t sc_capture(void)
{
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  struct v4l2_format fmt;
  struct pollfd pfd;
  void *addr[SC_NBUFFERS];
  size_t len[SC_NBUFFERS];
  ssize_t used = -EIO;
  int fd;
  int i;

  for (i = 0; i < SC_NBUFFERS; i++)
    {
      addr[i] = NULL;
      len[i]  = 0;
    }

  fd = open(SC_VIDEO_DEV, O_RDWR);
  if (fd < 0)
    {
      printf("social_cue: open %s failed, errno=%d\n", SC_VIDEO_DEV, errno);
      return -errno;
    }

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width       = SC_WIDTH;
  fmt.fmt.pix.height      = SC_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
  fmt.fmt.pix.sizeimage   = SC_SIZEIMAGE;

  if (ioctl(fd, VIDIOC_S_FMT, (unsigned long)&fmt) < 0)
    {
      printf("social_cue: S_FMT JPEG %dx%d failed, errno=%d\n",
             SC_WIDTH, SC_HEIGHT, errno);
      used = -errno;
      goto out;
    }

  memset(&req, 0, sizeof(req));
  req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_MMAP;
  req.count  = SC_NBUFFERS;

  if (ioctl(fd, VIDIOC_REQBUFS, (unsigned long)&req) < 0)
    {
      printf("social_cue: REQBUFS failed, errno=%d\n", errno);
      used = -errno;
      goto out;
    }

  for (i = 0; i < SC_NBUFFERS; i++)
    {
      memset(&buf, 0, sizeof(buf));
      buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index  = (uint32_t)i;

      if (ioctl(fd, VIDIOC_QUERYBUF, (unsigned long)&buf) < 0)
        {
          printf("social_cue: QUERYBUF[%d] failed, errno=%d\n", i, errno);
          used = -errno;
          goto out;
        }

      addr[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED,
                     fd, (off_t)buf.m.offset);
      if (addr[i] == MAP_FAILED)
        {
          addr[i] = NULL;
          printf("social_cue: mmap[%d] failed, errno=%d\n", i, errno);
          used = -errno;
          goto out;
        }

      len[i] = buf.length;

      if (ioctl(fd, VIDIOC_QBUF, (unsigned long)&buf) < 0)
        {
          printf("social_cue: QBUF[%d] failed, errno=%d\n", i, errno);
          used = -errno;
          goto out;
        }
    }

  if (ioctl(fd, VIDIOC_STREAMON, (unsigned long)&req.type) < 0)
    {
      printf("social_cue: STREAMON failed, errno=%d\n", errno);
      used = -errno;
      goto out;
    }

  pfd.fd     = fd;
  pfd.events = POLLIN;

  if (poll(&pfd, 1, SC_CAPTURE_TMO_MS) <= 0)
    {
      printf("social_cue: no frame within %d ms\n", SC_CAPTURE_TMO_MS);
      used = -ETIMEDOUT;
    }
  else
    {
      memset(&buf, 0, sizeof(buf));
      buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;

      if (ioctl(fd, VIDIOC_DQBUF, (unsigned long)&buf) < 0)
        {
          printf("social_cue: DQBUF failed, errno=%d\n", errno);
          used = -errno;
        }
      else
        {
          used = (ssize_t)buf.bytesused;
        }
    }

  ioctl(fd, VIDIOC_STREAMOFF, (unsigned long)&req.type);

out:
  for (i = 0; i < SC_NBUFFERS; i++)
    {
      if (addr[i] != NULL)
        {
          munmap(addr[i], len[i]);
        }
    }

  close(fd);
  return used;
}
```

**关键点**：
- ioctl 顺序固定为 `S_FMT → REQBUFS → (QUERYBUF+mmap+QBUF)×N → STREAMON → poll → DQBUF → STREAMOFF`，任何一步失败都 `goto out`，资源释放路径统一。
- **注意这个函数本身没有做 JPEG SOI/EOI 校验**——sc_capture() 只返回字节数，不检查内容（注释里明确说"the bytes are counted and then dropped"）。真正的 JPEG marker 校验逻辑在 `agent_camera_main.c` 的 `agent_camera_check_jpeg()`（见下）。移植 vs_media.c 时要自己加校验。
- 清理顺序：先 munmap 所有已映射的缓冲（用 NULL 判断哪些映射过），最后 close(fd)。**没有调用 VIDIOC_REQBUFS count=0 释放驱动侧的缓冲**——对比 `preview_jpeg_close()`（无此问题，因为没有反复开关）和 `tool_camera.c`（有，见下）。这是可能的资源泄漏点：多次调用 sc_capture 是否会累积驱动侧缓冲，取决于驱动在 close(fd) 时是否自动释放。ai_agent 的 `tool_camera.c::camera_v4l2_capture()`（`packages/ai_agent/src/tools/tool_camera.c` 第283-296行）在 cleanup 时显式调用 `VIDIOC_REQBUFS` 的 `count=0` 来释放缓冲，再 close(fd)，这个更保守的写法值得抄到 vs_media.c 里。
- poll 超时=5000ms，成功路径下 STREAMOFF 仍会执行；超时路径下也会 fallthrough 到 STREAMOFF（不会跳过）。

## 2. app/agent_camera/agent_camera_main.c — 几何协商 / JPEG校验 / base64导出

**几何协商**（`agent_camera_set_format`，第405-484行）：先按用户请求的宽高试 `V4L2_PIX_FMT_JPEG`，失败再试 `V4L2_PIX_FMT_ENTROPY`；如果 negotiate=true 且都失败，遍历 `VIDIOC_ENUM_FRAMESIZES` 找像素数最接近的尺寸重试。核心结构：
```c
static int agent_camera_set_format(int fd, int *width, int *height,
                                  bool negotiate, uint32_t *out_fmt)
{
  static const uint32_t candidates[] =
  {
    V4L2_PIX_FMT_JPEG,
    V4L2_PIX_FMT_ENTROPY,
  };
  struct agent_camera_size_s sizes[MAX_ENUM_SIZES];
  size_t c;

  for (c = 0; c < sizeof(candidates) / sizeof(candidates[0]); c++)
    {
      if (agent_camera_try_format(fd, *width, *height, candidates[c]) == OK)
        {
          *out_fmt = candidates[c];
          return OK;
        }
      /* ...打印失败原因... */
    }

  if (!negotiate) { return -EINVAL; }

  for (c = 0; c < sizeof(candidates) / sizeof(candidates[0]); c++)
    {
      /* 用 VIDIOC_ENUM_FRAMESIZES 枚举该格式的尺寸，选像素数最接近的，
       * 再用 agent_camera_try_format() 实际验证（因为枚举不保证按格式过滤）*/
    }
  return -EINVAL;
}
```
关键坑（代码注释明确指出）：`VIDIOC_ENUM_FRAMESIZES` 在这块板子上**不按 pixel_format 过滤**——驱动的 `capture_enum_frmsize()` 直接索引 imgsensor 的 frmsizes 数组，忽略 `f->pixel_format`，所以每个格式都会枚举出全部尺寸；唯一权威的验证方式是把候选尺寸真的送一次 `VIDIOC_S_FMT`。

**JPEG结构校验**（`agent_camera_check_jpeg`，第507-611行，比 SOI/EOI 更严格）：这个函数不是简单检查首尾两个 marker，而是完整走一遍 segment chain，因为该板子的硬件/软件编码器发出的 JPEG 有时**没有 SOS marker**（缺少 scan header），SOI/EOI 都在但 libjpeg 拒绝解码。函数逐字节扫描，跳过 marker 前的 0xFF 填充字节（该编码器会在 marker 前放 3 个额外 0xFF，如 `ff ff ff ff db`），识别 SOF(0xc0/0xc1)、DQT(0xdb)、DHT(0xc4)，遇到 SOS(0xda) 停止并标记 `have_sos=true`，遇到 EOI(0xd9) 也停止。最后打印 `SOF=/DQT=/DHT=/SOS=/EOI=` 五项校验结果，`!have_sos` 时打印明确的"NOT a decodable JPEG"警告。这是 vs_media.c 做 JPEG 校验时应该参考的完整版本，比 sc_capture 的（不存在的）简单版本更可靠。

**base64导出**（`agent_camera_print_b64`，第801-863行）：手写 base64 表 `"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"`，3字节输入编4字符输出，`B64_LINE_CHARS=252`（必须是4的倍数、且≤255，因为要配合 CP 桥的256字节日志行大小），行末补`\n`；用裸 `write(STDOUT_FILENO,...)`（`agent_camera_write_all`）而非 `printf`/`fwrite`，避免 stdio 缓冲区里再拷贝一份大帧；配合 `agent_camera_pace()` 按 `B64_CONSOLE_BPS=9600` 字节/秒的预算用 `clock_gettime(CLOCK_MONOTONIC,...)` 计算累计应该耗时多久、不够就 `usleep` 补齐，而不是固定每N行睡一次。前面还会打印 `agent_camera_fnv1a()`（FNV-1a 32位哈希，第698-711行）方便主机侧验证传输无损。

## 3. app/camera_preview/preview_jpeg.h — 硬件JPEG M2M封装接口

```c
struct preview_jpeg_s;   // 不透明句柄

// 打开 /dev/video1，协商 w×h VYUY 输入格式；返回 NULL 表示设备不存在
// (未编译 CONFIG_BK7258_JPEG_ENC 是正常情况，调用方应视为"无硬件JPEG可用"而非失败)
struct preview_jpeg_s *preview_jpeg_open(int w, int h, int quality);

// 编码一帧：frame/len 是捕获缓冲，会被拷贝进编码器自己的输出池（不能直接USERPTR传入，
// 驱动的 bk7258_jpeg_addr_ok() 只认自己池里的地址）。成功后 *out 指向编码器capture缓冲
// （在下次调用前有效），*outlen 是JPEG长度。
int preview_jpeg_encode(struct preview_jpeg_s *ctx,
                        const uint8_t *frame, size_t len,
                        const uint8_t **out, size_t *outlen);

// 上次encode耗时拆分：拷贝耗时 vs 编解码器耗时
void preview_jpeg_last_ms(struct preview_jpeg_s *ctx,
                          uint32_t *copy_ms, uint32_t *codec_ms);

void preview_jpeg_close(struct preview_jpeg_s *ctx);
```
实现（`preview_jpeg.c`）内部走的也是 V4L2 M2M 双队列：`VIDIOC_S_FMT`(OUTPUT, VYUY) → `VIDIOC_S_FMT`(CAPTURE, JPEG) → `VIDIOC_S_EXT_CTRLS`(质量) → REQBUFS/QUERYBUF/mmap(两个队列) → capture队列先QBUF → STREAMON(OUTPUT) → STREAMON(CAPTURE)。单次编码：拷贝帧到`ctx->in` → QBUF(OUTPUT) → poll(2000ms超时,`PJ_TIMEOUT_MS`) → DQBUF(CAPTURE)取结果 → 重新QBUF(CAPTURE)+DQBUF(OUTPUT)把两个缓冲还给驱动供下次复用。**用于 vs_media.c 时要注意**：`/dev/video1` 与 `/dev/video0`（预览用）**同时只能有一个所有者持有相机**，头文件注释明确说这是它属于 camera_preview 而非独立工具的原因——如果 vs_media.c 想用硬件JPEG M2M路径而不是像 sc_capture 那样软件JPEG，需要先确认没有其他进程占着 /dev/video0。

## 4. bk7258_psram_malloc() PSRAM动态分配API

头文件：`board/beken/chips/bk7258/include/bk7258_psram.h`（第68行起）
```c
void *bk7258_psram_malloc(size_t size);
void *bk7258_psram_zalloc(size_t size);
void *bk7258_psram_calloc(size_t n, size_t elem_size);
void *bk7258_psram_realloc(void *ptr, size_t size);
void *bk7258_psram_memalign(size_t alignment, size_t size);
void bk7258_psram_free(void *ptr);   // 释放函数
```
- 参数：`size` 请求字节数（`bk7258_psram_calloc` 是 n×elem_size，内部有溢出检查）。
- 失败返回：**NULL**，同时 `set_errno()` 设置——PSRAM未上电/未在线时是 `ENODEV`，分配失败（堆无空间）不显式设置但 `mm_malloc` 返回NULL。调用方必须检查 NULL。
- 实现（`bk7258_psram.c` 第346-361行）：
```c
void *bk7258_psram_malloc(size_t size)
{
  void *ptr = NULL;

  nxmutex_lock(&g_psram_lock);
  if (g_state == BK7258_PSRAM_ONLINE)
    {
      ptr = mm_malloc(g_psram_heap, size);
      if (ptr != NULL) { g_heap_allocations++; }
      else { g_heap_failures++; }
    }
  else
    {
      set_errno(ENODEV);
    }
  nxmutex_unlock(&g_psram_lock);
  return ptr;
}
```
关键点：内部用互斥锁保护，且只有 `g_state == BK7258_PSRAM_ONLINE` 时才真正分配——PSRAM 有掉电/恢复状态机（`BK7258_PSRAM_OFF/POWER_REQUESTED/PROBING/ONLINE/FREEZING/OFFLINE/RECOVERING/FAILED`），意味着**即使之前分配成功过，PSRAM 也可能在运行期间掉线**，长期持有的指针在 `bk7258_psram_power_lost()` 触发后可能失效——媒体驱动需要用 `bk7258_psram_contains()` 或 `bk7258_psram_is_online()` 校验，不能假设分配后永久有效。

**用法示例**（`app/audio_test/audio_test_ogg.c` 第645-676行）：
```c
h->packets = bk7258_psram_malloc((size_t)OGG_MAX_PACKET * OGG_PACKETS_PER_PAGE);
if (h->packets == NULL)
  {
    free(h);
    return NULL;
  }
...
if (!prefer_psram)
  {
    h->enc = malloc((size_t)encsize);   /* 优先SRAM：PSRAM是non-cacheable，频繁访问的状态放PSRAM会慢 */
  }
if (h->enc == NULL)
  {
    h->encmem = bk7258_psram_malloc((size_t)encsize);
    h->enc = (OpusEncoder *)h->encmem;
  }
if (h->enc == NULL)
  {
    bk7258_psram_free(h->packets);   /* 失败要把之前分配的也释放 */
    free(h);
    return NULL;
  }
```
销毁配对（`audio_test_ogg_encoder_destroy`）：
```c
if (h->encmem != NULL) { bk7258_psram_free(h->encmem); }
else { free(h->enc); }          /* 用哪个分配器分配就要用对应的释放函数 */
if (h->packets != NULL) { bk7258_psram_free(h->packets); }
free(h);
```
另有 `app/audio_test/audio_test_stream.c`（第665、674行）和 `app/audio_test/audio_test_main.c`（第1282行）、`bk7258_jpeg_enc.c`（第733行，JPEG编码器的de-interleave scratch buffer）在用同一模式。**规律**：PSRAM分配失败时必须回滚之前已分配的资源再返回NULL/errno，不能只 free 当前这一个。

## 5. app/conv/conv_store.c / conv_store.h — 索引+记录文件实现

**8.3命名格式**（`conv_store.h` 第67-83行）：
```c
#define CONV_DIR          "/mnt/sdnand/ai_agent"
#define CONV_SUBDIR       CONV_DIR "/conv"
#define CONV_INDEX        CONV_SUBDIR "/INDEX.TXT"
#define CONV_FMT_TEXT     CONV_SUBDIR "/C%04u.TXT"    /* 转录文本 */
#define CONV_FMT_CUE      CONV_SUBDIR "/C%04u.JSN"    /* social-cue/v1 分析结果 */
```
`C%04u` 即 `C0001.TXT` 这种8.3合法格式（前缀C+4位数字=5字符，扩展名3字符）。

**重要发现——conv_store.c 并未使用"临时文件→fsync→rename"的原子写入流程**。它直接用 `fopen(path,"w")` → `fputs` → `fclose`（见下方 `conv_store_append`），没有 fsync、没有临时文件。真正的原子写模式在本仓库里是 `app/provisioning_web/vp_store.c::vp_store_save()`（第304-355行），流程是：
```c
stream = fopen(tmp, "wb");                          /* 临时文件，同目录下 "vpsave.tmp" */
fwrite(record, 1, sizeof(record), stream);
fflush(stream) != 0 || fsync(fileno(stream)) != 0   /* 落盘，否则rename后数据可能还没到盘 */
fclose(stream);
rename(tmp, path);                                   /* 原子替换 */
sync();
```
如果 vs_history.c 需要断电安全，应该抄这个模式，而不是 conv_store.c 的模式（conv_store.c 依赖的是"索引写在最后"这种逻辑原子性，允许索引和记录之间不一致但通过写入顺序保证安全失败方向，见下）。

**conv_store_append 完整代码**（记录写入，索引最后写）：
```c
int conv_store_append(struct conv_entry_s *entry, const char *transcript,
                      const char *cue_json)
{
  char path[64];
  FILE *f;

  if (entry == NULL || transcript == NULL || cue_json == NULL)
    {
      return -EINVAL;
    }

  entry->seq = conv_store_next_seq();
  entry->text_bytes = strlen(transcript);

  snprintf(path, sizeof(path), CONV_FMT_TEXT, entry->seq);
  f = fopen(path, "w");
  if (f == NULL)
    {
      printf("conv: cannot write %s: %d\n", path, errno);
      return -errno;
    }
  fputs(transcript, f);
  fclose(f);

  snprintf(path, sizeof(path), CONV_FMT_CUE, entry->seq);
  f = fopen(path, "w");
  if (f == NULL) { return -errno; }
  fputs(cue_json, f);
  fclose(f);

  /* 索引最后写：记录存在但索引没有它=不可见但无害；
   * 索引指向不完整的记录=查询会失败。这是有意选择的失败方向。 */
  f = fopen(CONV_INDEX, "a");
  if (f == NULL)
    {
      printf("conv: cannot append to %s: %d\n", CONV_INDEX, errno);
      return -errno;
    }
  fprintf(f, "%u|%lu|%u|%s|%.2f|%d|%zu|%s\n",
          entry->seq, (unsigned long)entry->epoch, entry->duration_ms,
          entry->cue, (double)entry->confidence,
          entry->unable_to_judge ? 1 : 0, entry->text_bytes,
          entry->summary);
  fclose(f);
  return OK;
}
```
索引行格式是 `seq|epoch|duration_ms|cue|confidence|unable|text_bytes|summary`（管道分隔，非JSON——理由：板端只需要读，写JSON在C里成本高，读JSON需要解析器和内存）。

**记录读取/追加/遍历函数签名**（`conv_store.h`）：
```c
int conv_store_ready(void);                                    /* 建目录，检查 /mnt/sdnand 是否已挂载 */
int conv_store_append(struct conv_entry_s *entry,
                      const char *transcript, const char *cue_json);
int conv_store_query(const struct conv_filter_s *filter,
                     conv_visit_t visit, void *arg);            /* 顺序遍历INDEX.TXT，两阶段过滤 */
unsigned int conv_store_next_seq(void);                         /* 扫描INDEX.TXT取最大seq+1 */
int conv_store_clear(void);                                     /* 按索引删除记录文件，索引最后删 */
int conv_store_read_file(const char *fmt, unsigned int seq,
                         char *buf, size_t len);
int conv_store_read_raw(const char *path, char *buf, size_t len);
unsigned int conv_epoch_to_date(uint32_t epoch);                /* epoch↔YYYYMMDD，纯整数运算 */
uint32_t conv_date_to_epoch(unsigned int yyyymmdd, bool end_of_day);
```
`conv_store_query` 的两阶段过滤逻辑（第283-350行区域）：先用索引行本身能判断的条件（日期范围、cue、置信度、unable_to_judge）过滤，通过的再检查 `summary` 字段（已在内存里，不用开文件），最后才靠 `conv_transcript_has()` 流式打开转录文件做关键字搜索（**注意**：关键字长度不能超过 `CONV_SCAN_CHUNK=256` 字节，否则直接返回false并打印警告，这是流式滑动窗口搜索的已知限制）。这个"索引优先、按需开文件"的模式非常适合 vs_history.c 参考，因为需求2里提到的是"记录读取/追加/遍历"，和 conv_store 的需求高度重合，唯独原子写入部分要换成 vp_store.c 的模式。

## 6. app/velasight/vs_config.c — SD-NAND挂载等待逻辑

**注意**：`vs_config.c` 里等待的其实是通用的 `bk7258_mmcsd_status()`（用于任何走 `/mnt/sdnand` 的场景，包含Wi-Fi配网记录），不是专门为 vs_history/vs_media 写的，但逻辑可以照搬。完整实现（第10-33行）：
```c
static int vs_config_wait_for_store(void)
{
#ifdef CONFIG_BK7258_SDIO
  char source[32];
  bool mounted;
  unsigned int attempt;

  /* Automount may be delayed by up to 60 seconds, followed by the card probe
   * timeout.  Keep this bounded but long enough for every legal Kconfig value.
   */
  for (attempt = 0; attempt < 700; attempt++)
    {
      if (bk7258_mmcsd_status(&mounted, source, sizeof(source)) == 0 &&
          mounted)
        {
          return 0;
        }

      usleep(100000);
    }

  return -ETIMEDOUT;
#else
  return -ENODEV;
#endif
}
```
**轮询间隔**：100ms（`usleep(100000)`）。**总超时次数**：700次 → 总计约70秒。**检查的标志**：`bk7258_mmcsd_status(&mounted, source, sizeof(source))`（声明在 `board/beken/boards/bk7258/bk7258-ap/include/board.h` 第56行），返回值为0且 `mounted==true` 才算成功，`source` 参数拿到的是挂载源设备名（这里没用到）。该函数本身只是读一个由后台 worker（`bk7258_mmcsd_worker`，在 `bk7258_mmcsd.c`）维护的、加锁保护的状态标志 `g_mmcsd_mounted`，不会阻塞。70秒的由来是注释里写的："自动挂载最多延迟60秒，加上卡探测超时"——这是实测确定的上限。

调用方式：`vs_config_load_wifi()` 用一个静态 `first_load` 标志确保这个等待只在第一次调用时跑一次（第46-58行），避免每次调用都重新等70秒。vs_history.c/vs_media.c 如果也要等 SD-NAND，可以复用同样的模式，但注意 `conv_store_ready()`（问题5的代码）用的是另一种更轻量的判断方式——直接 `stat("/mnt/sdnand", &st)`，如果失败就返回 `-ENODEV` 并打印提示，不做轮询等待。两种策略的区别：`vs_config` 是"阻塞等到位"（适合启动期一次性关键路径），`conv_store_ready` 是"立即检查、失败就报错"（适合命令触发式场景，不应阻塞NSH命令行70秒）。**根据 IDLE_AI_MODE_INTEGRATION_PLAN.md 的规则0.2第1条，UI/按键热路径禁止阻塞式SD-NAND等待**，所以 vs_media.c/vs_history.c 大概率应该用 `conv_store_ready()` 的立即检查模式，而不是 `vs_config_wait_for_store()` 的70秒轮询模式——这点在移植时要特别注意，别把等待逻辑抄错了场景。

## 7. NuttX V4L2头文件 / GC2145分辨率表

**头文件路径**：这个代码库里没有叫 `videodev2.h` 的文件——NuttX 把等价物叫 **`include/sys/videoio.h`**（绝对路径：`/home/mi/vela_competition/contest/nuttx/include/sys/videoio.h`）。文件头注释明确写着"参考自 FreeBSD 的 `videodev2.h`"，所以概念上是同一个东西，换了名字。它定义了 `V4L2_PIX_FMT_*`、`v4l2_fourcc()`、`struct v4l2_format`等所有V4L2结构体和常量。项目里 `#include <sys/videoio.h>` 的地方：`social_cue_main.c`、`camera_preview_main.c`、`preview_jpeg.c`、`jpeg_test_main.c`、`bk7258_camera_imgsensor.c`。另有 `nuttx/include/nuttx/video/video.h` 只是 `#include <sys/videoio.h>` 的薄包装（加了 ioctl 处理函数声明），agent_camera_main.c 和 ai_agent 的 tool_camera.c 引用的是这一层（`#include <nuttx/video/video.h>`）。

**GC2145 支持的分辨率**：在 `board/beken/boards/bk7258/bk7258-ap/src/bk7258_camera_imgsensor.c` 第1171-1184行的 `g_gc2145_modes[]` 数组：
```c
static const struct gc2145_mode g_gc2145_modes[] =
{
  { 480, 480, GC2145_REGS(g_gc2145_480_480_regs), NULL, 0 },
  { 640, 480, GC2145_REGS(g_gc2145_640_480_regs),
    g_gc2145_640_480_fps, sizeof(g_gc2145_640_480_fps) / sizeof(g_gc2145_640_480_fps[0]) },
  { 864, 480, GC2145_REGS(g_gc2145_864_480_regs),
    g_gc2145_864_480_fps, sizeof(g_gc2145_864_480_fps) / sizeof(g_gc2145_864_480_fps[0]) },
};
#define GC2145_MODE_COUNT (sizeof(g_gc2145_modes) / sizeof(g_gc2145_modes[0]))
```
即 **480x480 / 640x480 / 864x480** 三档，480x480无独立帧率表（`nfps=0`，用窗口表固定的帧率）。**`bk7258_gc2145_find_mode()`**（同文件第1546-1560行）：
```c
static FAR const struct gc2145_mode *
bk7258_gc2145_find_mode(uint16_t width, uint16_t height)
{
  size_t i;
  for (i = 0; i < GC2145_MODE_COUNT; i++)
    {
      if (g_gc2145_modes[i].width == width && g_gc2145_modes[i].height == height)
        {
          return &g_gc2145_modes[i];
        }
    }
  return NULL;
}
```
这是**精确匹配**，不是最近邻——任何不在这三档里的宽高（比如 320x180、1280x720）会直接返回NULL，上层 `VIDIOC_S_FMT` 处理函数据此拒绝。代码注释还提到 1280x720/1600x1200 的寄存器表其实存在于源码里，但**故意没有**加入 `g_gc2145_modes[]`——因为1280x720在硬件上实测会把整个板子拖死（CP的IPC watchdog超时断言），怀疑是PSRAM持续写带宽不够（640x480下约37MB/s，1280x720会到约105MB/s）。这是重要的"已知不能用"信息，vs_media.c 选分辨率时必须限制在这三档内。

## 8. mbedtls_base64_encode 用法

**头文件**：`"mbedtls/base64.h"`（mbedtls标准API，来自 `apps/crypto/mbedtls/mbedtls`），签名为：
```c
int mbedtls_base64_encode(unsigned char *dst, size_t dlen, size_t *olen,
                          const unsigned char *src, size_t slen);
```
参数顺序：目的缓冲、目的缓冲容量、**输出**实际写入/需要的长度、源数据、源数据长度。返回0成功，`MBEDTLS_ERR_BASE64_BUFFER_TOO_SMALL` 表示dlen不够（这时`*olen`会被设为所需大小）。

**用法1——两阶段调用（先探测长度再编码）**，`packages/ai_agent/src/llm/llm_vision.c` 的 `llm_chat_vision_raw()`（第236-260行）：
```c
size_t b64_len = 0;
mbedtls_base64_encode(NULL, 0, &b64_len, raw_image, raw_len);   /* dst=NULL探测所需长度 */

/* ...根据 b64_len 算出 body 缓冲总大小并 malloc... */

size_t written = 0;
int rc = mbedtls_base64_encode(
    (unsigned char*)(body + off),
    total - (size_t)off - strlen(trailer) - 1,
    &written, raw_image, raw_len);
if (rc != 0)
  {
    free(body);
    snprintf(response_buf, buf_size, "Error: base64 encode failed (%d)", rc);
    return ERROR;
  }
off += (int)written;
```
这是把JPEG直接编码进JSON请求体里拼好的data URI，避免了先编码到独立buffer再拼接的二次拷贝——直接编码到最终body里目标偏移处。这是 vs_media.c 给 `llm_chat_vision_raw` 传原始bytes时最值得参考的调用方式（虽然 `llm_chat_vision_raw` 内部自己会调用 base64 编码，调用方通常直接传原始JPEG字节，不需要自己编码——除非走的是 `llm_chat_vision()` 那个需要预先b64字符串的接口）。

**用法2——WebSocket握手key编码**，`packages/ai_agent/src/voice/volc_asr.c` 的 `ws_upgrade()`（第276-283行）：
```c
unsigned char key_raw[16];
unsigned char key_b64[32];
size_t key_b64_len;

asr_entropy_func(NULL, key_raw, sizeof(key_raw));
mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len,
    key_raw, sizeof(key_raw));
```
这里是已知输入长度（16字节固定），提前分配够大的输出buffer（32字节，base64编码16字节需要24字符+NUL，32足够），一次调用完成，不需要两阶段。

两种用法的选择依据：**输入长度可变或很大时用两阶段（先探测再分配再编码）**，**输入长度固定且小时直接给足够大的静态buffer一次编码**。vs_media.c 如果要把JPEG bytes传给云端多模态接口，直接调用 `llm_chat_vision_raw(prompt, jpeg_data, jpeg_len, "image/jpeg", resp, cap)` 即可，不需要自己手动调 mbedtls_base64_encode——该函数已经内置了两阶段编码逻辑。

