    free(s_voice.pcm_buf);
    s_voice.pcm_buf = NULL;
    /* Spawn ASR worker thread */
    int ret = agent_task_create(asr_and_dispatch, "asr_worker",
        ASR_THREAD_STACK, pkg, AGENT_VOICE_PRIO);
    if (ret != OK) {
        free(pkg);
        return -EIO;
    }
    return 0;
}
