static int ensure_scratch_capacity(audio_capture_t* cap, size_t need)
{
    if (cap->scratch_size >= need) {
        return 0;
    }
    unsigned char* scratch = realloc(cap->scratch, need);
    if (!scratch) {
        return -ENOMEM;
    }
    cap->scratch = scratch;
    cap->scratch_size = need;
    return 0;
