## 4. `app/provisioning_web/vp_http.c`（556 行）完整分析

### 支持的 HTTP 路径（在 `vp_http_parse()`，第 103-330 行）

```c
int vp_http_parse(const char *buf, size_t len, struct vp_http_request_s *req)
{
  /* ... 找 \r\n\r\n 结束标记，headers_len 超过 VP_HTTP_MAX_HEADERS 返回 431 ... */

  /* Request line 解析：取方法(GET/POST)和 target(路径) */
  if ((size_t)(sp1 - line) == 3 && memcmp(line, "GET", 3) == 0)
    is_post = false;
  else if ((size_t)(sp1 - line) == 4 && memcmp(line, "POST", 4) == 0)
    is_post = true;
  else
    return vp_reject(req, 405);          /* 其他方法 → 405 */

  {
    const char *target = sp1 + 1;
    const char *query = memchr(target, '?', targetlen);
    size_t pathlen = query != NULL ? (size_t)(query - target) : targetlen;

    if (!is_post)
      {
        bool root = pathlen == 1 && target[0] == '/';
        bool index = pathlen == 11 && memcmp(target, "/index.html", 11) == 0;

        if (!root && !index)
          return vp_reject(req, 404);     /* GET 其他路径 → 404 */

        req->action = VP_HTTP_ACTION_PAGE;
        return 0;
      }

    if (pathlen != 5 || memcmp(target, "/save", 5) != 0)
      return vp_reject(req, 404);         /* POST 非 /save → 404 */
  }

  /* Headers：只认 transfer-encoding(拒绝chunked)、content-type(须form-urlencoded)、
   * content-length(须存在，且 <= VP_HTTP_MAX_BODY) */
  /* ... */

  req->action = VP_HTTP_ACTION_SAVE;
  req->status = 200;
  req->content_length = content_length;
  return 0;
}
```

**当前仅支持 3 个具体路径**：`GET /`、`GET /index.html`、`POST /save`。**路径匹配是纯手写的长度+`memcmp`比较，没有查表/正则/前缀匹配机制**，扩展新路径必须在这个函数里手写新的 if 分支。

### `vp_http_form_page_with_ssid` / `vp_http_saved_page`（完整实现，第 434-524 行）

```c
static size_t vp_http_form_page_notice(char *buf, size_t buflen,
                                       const char *notice,
                                       const char *current_ssid,
                                       bool saved)
{
  char escaped[256];
  char escaped_ssid[VELASIGHT_PROV_SSID_MAX * 6 + 1];
  char ssid_attr[VELASIGHT_PROV_SSID_MAX * 6 + 16];
  char body[VP_HTTP_BODY_BUILD];      /* 2048 */
  int bodylen;

  if (buf == NULL) return 0;

  escaped[0] = '\0';
  escaped_ssid[0] = '\0';
  ssid_attr[0] = '\0';
  if (current_ssid != NULL)
    {
      if (vp_html_escape(current_ssid, escaped_ssid, sizeof(escaped_ssid)) >= 0)
        snprintf(ssid_attr, sizeof(ssid_attr), "value=\"%s\" ", escaped_ssid);
    }
  if (notice != NULL && vp_html_escape(notice, escaped, sizeof(escaped)) < 0)
    escaped[0] = '\0';

  bodylen = snprintf(body, sizeof(body),
                     VP_PAGE_HEAD
                      "<h1>设备配网</h1>"
                      "<p class=\"note\">当前存储的 Wi-Fi：<strong>%s</strong></p>"
                      "%s%s%s"
                     "<form action=\"/save\" method=\"post\">"
                     "<label for=\"ssid\">网络名称（SSID）</label>"
                      "<input id=\"ssid\" name=\"ssid\" type=\"text\" "
                      "maxlength=\"32\" %sautocapitalize=\"off\" required>"
                     "<label for=\"password\">密码（开放网络留空）</label>"
                      "<input id=\"password\" name=\"password\" "
                      "type=\"password\" maxlength=\"63\">"
                       /* ...mimo_apikey / volc_appid / volc_token 三个字段... */
                     "<button type=\"submit\">保存</button>"
                     "</form>"
                      "<p class=\"note\">保存后可在设备上长按返回。</p>"
                      VP_PAGE_TAIL,
                      escaped_ssid[0] != '\0' ? escaped_ssid : "未配置",
                      escaped[0] != '\0' ? saved ? "<p class=\"ok\">" : "<p class=\"err\">" : "",
                      escaped,
                      escaped[0] != '\0' ? "</p>" : "",
                      ssid_attr);

  if (bodylen < 0) return 0;
  return vp_wrap(buf, buflen, 200, body, (size_t)bodylen);
}

size_t vp_http_form_page_with_ssid(char *buf, size_t buflen,
                                   const char *notice, const char *current_ssid)
{
  return vp_http_form_page_notice(buf, buflen, notice, current_ssid, false);
}

size_t vp_http_form_page(char *buf, size_t buflen, const char *notice)
{
  return vp_http_form_page_with_ssid(buf, buflen, notice, NULL);
}

size_t vp_http_saved_page(char *buf, size_t buflen, const char *ssid,
                          uint32_t generation, bool open_network)
{
  (void)generation;
  (void)open_network;
  return vp_http_form_page_notice(buf, buflen, "已保存", ssid, true);
}
```

### 响应生成机制：`vp_wrap()`（第 415-433 行）—— 就是 `snprintf` 拼字符串

```c
static size_t vp_wrap(char *buf, size_t buflen, int status,
                      const char *body, size_t bodylen)
{
  int header;

  header = snprintf(buf, buflen,
                    "HTTP/1.1 %d %s\r\n"
                    "Content-Type: text/html; charset=utf-8\r\n"
                    "Content-Length: %u\r\n"
                    "Cache-Control: no-store\r\n"
                    "%s"
                    "Connection: close\r\n"
                    "\r\n",
                    status, vp_reason(status), (unsigned)bodylen,
                    status == 405 ? "Allow: GET, POST\r\n" : "");

  if (header < 0 || (size_t)header + bodylen + 1 > buflen)
    return 0;

  memcpy(buf + header, body, bodylen);
  buf[(size_t)header + bodylen] = '\0';
  return (size_t)header + bodylen;
}
```

流程是：先用 `snprintf` 把 HTML body 拼进一个 2048 字节的栈上 `body[]` 数组，再用 `vp_wrap()` 把响应头（固定用 `Content-Type: text/html`、精确的 `Content-Length`、`Connection: close`）和 body 一起 `memcpy` 进传入的响应缓冲区（`g_response[VP_HTTP_RESPONSE_MAX]`，4096 字节）。**整个响应必须一次性放进一个固定大小的缓冲区**——这是当前架构的核心限制。

### 文件下载相关代码：**不存在**
`vp_http.c`/`vp_http.h` 全文搜索没有 `Content-Disposition`、没有分块传输、没有任何二进制文件读取/发送逻辑。所有响应都是 `Content-Type: text/html; charset=utf-8` 的固定 HTML 字符串（`vp_reason()` 只认识 200/400/404/405/411/413/415/431/500 几个状态码，都是文本错误页）。**这个模块从设计上就是"一个表单 + 一次提交"，没有任何静态文件/二进制流的服务能力可以直接复用。**

