### 1.4 六个公开函数的完整实现

```c
int vs_history_open(void)
{
  int ret;

  if (g_ready)
    {
      return 0;
    }

  ret = vs_history_wait_for_store();
  if (ret < 0)
    {
      printf("vs_history: store unavailable (%d), using seed data\n", ret);
      vs_history_load_seed();
      g_ready = true;
      return ret;
    }

  mkdir("/mnt/sdnand/ai_agent", 0700);
  mkdir(VS_HISTORY_DIR, 0700);

  ret = vs_history_load_index();
  if (ret < 0)
    {
      printf("vs_history: no usable index (%d), seeding\n", ret);
      vs_history_load_seed();
    }
  else
    {
      printf("vs_history: loaded %u record(s) from %s\n", g_count,
             VS_HISTORY_INDEX);
    }

  g_ready = true;
  return 0;
}

unsigned int vs_history_count(void)
{
  return g_count;
}

int vs_history_get_index(unsigned int i, struct vs_history_index_s *out)
{
  if (out == NULL || i >= g_count)
    {
      return -EINVAL;
    }

  *out = g_index[i];
  return 0;
}

int vs_history_read_full(const char *record_key, char *buf, size_t len)
{
  char path[64];
  FILE *f;
  long sz;
  int n;

  if (record_key == NULL || buf == NULL || len == 0)
    {
      return -EINVAL;
    }

  snprintf(path, sizeof(path), "%s/%s.JSN", VS_HISTORY_DIR, record_key);

  f = fopen(path, "r");
  if (f == NULL)
    {
      return -ENOENT;
    }

  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) < 0 ||
      fseek(f, 0, SEEK_SET) != 0)
    {
      fclose(f);
      return -EIO;
    }

  if (sz >= (long)len)
    {
      sz = (long)len - 1;
    }

  n = (int)fread(buf, 1, (size_t)sz, f);
  fclose(f);
  buf[n] = '\0';
  return n;
}

int vs_history_append(struct vs_history_index_s *index,
                      const char *full_json)
{
  char path[64];
  char tmp[64];
  unsigned int seq;
  int ret;

  if (index == NULL)
    {
      return -EINVAL;
    }

  if (!g_ready)
    {
      return -ENODEV;
    }

  if (g_count >= CONFIG_VS_HISTORY_MAX_RECORDS)
    {
      return -ENOSPC;
    }

  seq = g_next_seq;
  snprintf(index->record_key, sizeof(index->record_key), "R%08u", seq);

  if (full_json != NULL)
    {
      snprintf(path, sizeof(path), VS_HISTORY_FMT_JSN, seq);
      snprintf(tmp, sizeof(tmp), VS_HISTORY_FMT_TMP, seq);

      ret = vs_history_atomic_write(tmp, path, full_json);
      if (ret < 0)
        {
          return ret;
        }
    }

  /* Insert at the front: index 0 is always the newest ... */
  memmove(&g_index[1], &g_index[0],
          g_count * sizeof(g_index[0]));
  g_index[0] = *index;
  g_count++;
  g_next_seq = seq + 1;

  ret = vs_history_save_index();
  if (ret < 0)
    {
      printf("vs_history: index save failed (%d), record %s kept in "
             "memory only\n", ret, index->record_key);
    }

  return 0;
}

void vs_history_close(void)
{
  g_ready = false;
  g_count = 0;
  g_next_seq = 0;
}
```

**重要 bug 提示**：`vs_history_append()` 里的 `memmove(&g_index[1], &g_index[0], g_count * sizeof(g_index[0]));` 是在 `g_count` 还没自增之前执行的，把 `g_count` 个元素往后挪一位——当 `g_count == CONFIG_VS_HISTORY_MAX_RECORDS - 1` 时，`&g_index[1]` 到 `&g_index[g_count]`（即数组最后一个合法下标）都会被写入，这正好落在数组边界内（因为前面已经用 `g_count >= CONFIG_VS_HISTORY_MAX_RECORDS` 挡掉了满的情况），所以不会越界，但这里没有主动淘汰旧记录的逻辑——一旦达到上限，`vs_history_append()` 直接返回 `-ENOSPC`，旧记录既不会被顶掉也不会自动清理磁盘文件。重构时如果想要"环形覆盖最旧记录"，这里需要新增逻辑。

### 1.5 原子写入 `vs_history_atomic_write()`（`vs_history.c:303-353`，被索引保存和记录正文保存共用）

```c
static int vs_history_atomic_write(const char *tmp, const char *dest,
                                   const char *text)
{
  size_t len = strlen(text);
  int fd;
  ssize_t written;

  fd = open(tmp, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return -errno;
    }

  written = write(fd, text, len);
  if (written < 0 || (size_t)written != len || fsync(fd) < 0)
    {
      int err = errno != 0 ? -errno : -EIO;

      close(fd);
      unlink(tmp);
      return err;
    }

  if (close(fd) < 0)
    {
      int err = -errno;

      unlink(tmp);
      return err;
    }

  if (rename(tmp, dest) < 0)
    {
      int err = -errno;

      unlink(tmp);
      return err;
    }

  /* Best-effort directory fsync ... */
  fd = open(VS_HISTORY_DIR, O_RDONLY);
  if (fd >= 0)
    {
      fsync(fd);
      close(fd);
    }

  return 0;
}
```
流程：`open(tmp, O_CREAT|O_TRUNC)` → `write` → `fsync(fd)` → `close(fd)` → `rename(tmp, dest)` → 打开目录 `VS_HISTORY_DIR` 做一次 best-effort `fsync` 让 rename 落盘。任何一步失败都会 `unlink(tmp)` 清理临时文件再返回负 errno。`vs_history_append()` 里记录正文先落盘再更新索引（先写 `R%08u.JSN`，成功后才 `vs_history_save_index()`），文件头注释解释了这个顺序：崩溃在两者之间，宁可留下"索引里没提到的孤儿记录文件"，也不留下"索引指向不存在文件"的坑。

其余私有函数（`vs_history_wait_for_store` 等 SD-NAND 挂载轮询、`vs_history_load_seed`、`vs_history_parse_entry` 逐字段容错解析、`vs_history_load_index` 整体加载、`vs_history_entry_to_json`、`vs_history_save_index`）均已在上方内容中完整体现（详见 `app/velasight/vs_history.c` 全文，109-392行）。

