## 4. `vs_voice.c` 完整现状

### 4.1 `struct vs_voice_ctx_s`（`vs_voice.c:152-160`）

```c
struct vs_voice_ctx_s
{
  char record_key[VS_HISTORY_KEY_MAX];
  char title[VS_VOICE_TITLE_MAX];
  char summary[VS_VOICE_SUMMARY_MAX];
  char date[VS_TEXT_SHORT];
  char body[VS_VOICE_BODY_MAX];
  bool content_truncated;
};
```
其中 `VS_VOICE_TITLE_MAX=96, VS_VOICE_SUMMARY_MAX=192, VS_VOICE_BODY_MAX=768`（`vs_voice.c:123-125`）。**这个结构体在 `vs_voice_worker()` 里是局部栈变量**（`struct vs_voice_ctx_s record_ctx;`），每轮问答重新清零重新填充，不是 `static`/全局，不跨轮次保留。

### 4.2 `vs_voice_worker()` 完整流程（`vs_voice.c:802-975`附近）

```c
static void *vs_voice_worker(void *arg)
{
  struct vs_voice_request_s request = *(struct vs_voice_request_s *)arg;
  struct vs_media_frame_s frame;
  struct vs_voice_ctx_s record_ctx;
  char question[VS_VOICE_QUESTION_MAX];
  char *prompt = NULL;
  char *model_resp = NULL;
  char *answer = NULL;
  char display_text[VS_TEXT_LONG];
  bool should_speak;
  bool have_frame = false;
  int ret;

  free(arg);
  memset(&frame, 0, sizeof(frame));

  prompt     = malloc(CONFIG_VS_VOICE_PROMPT_MAX_BYTES);
  model_resp = malloc(CONFIG_VS_VOICE_RESP_MAX_BYTES);
  answer     = malloc(VS_VOICE_ANSWER_MAX);
  if (prompt == NULL || model_resp == NULL || answer == NULL)
    {
      vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, -ENOMEM, NULL);
      goto cleanup;
    }

  /* Step 1 (photo path only): one still frame */
  if (request.ctx == VS_VOICE_CTX_PHOTO)
    {
      vs_voice_set_stage(VS_VOICE_STAGE_PHOTO);
      ret = vs_media_capture_jpeg(&frame, CONFIG_VS_PHOTO_WIDTH, CONFIG_VS_PHOTO_HEIGHT);
      if (vs_voice_is_cancelled()) goto cleanup;
      if (ret < 0)
        {
          vs_voice_post(VS_APP_EVENT_PHOTO_FAILED, request.request_id, ret, NULL);
          goto cleanup;
        }
      have_frame = true;
      vs_voice_post(VS_APP_EVENT_PHOTO_READY, request.request_id, 0, "ok");
    }

  /* Step 2: record + recognize */
  vs_voice_set_stage(VS_VOICE_STAGE_RECORDING);
  ret = vs_voice_record_and_recognize(question, sizeof(question));
  if (vs_voice_is_cancelled() || ret == -ECANCELED) goto cleanup;
  if (ret < 0)
    {
      vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, ret, NULL);
      goto cleanup;
    }
  vs_voice_post(VS_APP_EVENT_VOICE_LISTENING_DONE, request.request_id, 0, NULL);
  vs_voice_set_stage(VS_VOICE_STAGE_THINKING);

  /* Step 3: build the prompt and call the model */
  if (request.ctx == VS_VOICE_CTX_RECORD)
    {
      if (!vs_voice_load_record_ctx(request.record_key, &record_ctx))
        {
          vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, -ENOENT, NULL);
          goto cleanup;
        }
      ret = vs_voice_build_record_messages(&record_ctx, question, prompt,
                                           CONFIG_VS_VOICE_PROMPT_MAX_BYTES);
      if (ret < 0)
        {
          vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, ret, NULL);
          goto cleanup;
        }
      ret = llm_chat(VS_VOICE_SYSTEM_PROMPT, prompt, model_resp,
                     CONFIG_VS_VOICE_RESP_MAX_BYTES);
    }
  else
    {
      ret = vs_voice_build_photo_prompt(question, prompt, CONFIG_VS_VOICE_PROMPT_MAX_BYTES);
      if (ret < 0)
        {
          vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, ret, NULL);
          goto cleanup;
        }
      ret = have_frame ?
            llm_chat_vision_raw(prompt, frame.data, frame.len, "image/jpeg",
                                model_resp, CONFIG_VS_VOICE_RESP_MAX_BYTES) :
            -ENODATA;
    }

  if (have_frame) { vs_media_frame_release(&frame); have_frame = false; }
  if (vs_voice_is_cancelled()) goto cleanup;
  if (ret != OK)
    {
      printf("vs_voice: model call failed: %.100s\n", model_resp);
      vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, -EIO, NULL);
      goto cleanup;
    }

  /* Step 4: parse, truncate, deliver */
  ret = vs_voice_parse_reply(model_resp, display_text, sizeof(display_text),
                             answer, VS_VOICE_ANSWER_MAX, &should_speak);
  if (ret < 0)
    {
      vs_voice_post(VS_APP_EVENT_VOICE_FAILED, request.request_id, ret, NULL);
      goto cleanup;
    }
  vs_voice_utf8_truncate(display_text, VS_TEXT_LONG - 1);
  vs_voice_post(VS_APP_EVENT_VOICE_REPLY, request.request_id, 0, display_text);
  if (vs_voice_is_cancelled()) goto cleanup;

  /* Step 5: speak */
  if (should_speak)
    {
      vs_voice_speak(answer);
    }

cleanup:
  if (have_frame) vs_media_frame_release(&frame);
  free(prompt); free(model_resp); free(answer);
  pthread_mutex_lock(&g_voice.lock);
  g_voice.busy  = false;
  g_voice.stage = VS_VOICE_STAGE_IDLE;
  pthread_mutex_unlock(&g_voice.lock);
  return NULL;
}
```
**关键点**：Step 5 的 `vs_voice_speak(answer)` 是**同步阻塞调用**，播完（或被 `vs_voice_stop_speaking()`/`vs_voice_cancel()` 中断）后函数直接走到 `cleanup`，**没有向 `vs_app.c` 投递任何"播报完成"事件**——UI 侧要靠用户按键（见第6节）才会离开 `VS_PAGE_VOICE_SPEAKING`。

### 4.3 Prompt 构造代码

**`vs_voice_build_record_messages()`**（`vs_voice.c:483-552`，历史记录问答路径，构造 `llm_chat()` 需要的 messages JSON 数组）：
```c
static int vs_voice_build_record_messages(const struct vs_voice_ctx_s *ctx,
                                          const char *question,
                                          char *out, size_t out_cap)
{
  cJSON *array;
  cJSON *msg;
  char *content;
  char *text;
  int content_len;
  int ret = -ENOMEM;

  content = malloc(CONFIG_VS_VOICE_PROMPT_MAX_BYTES);
  if (content == NULL) return -ENOMEM;

  content_len = snprintf(content, CONFIG_VS_VOICE_PROMPT_MAX_BYTES,
                         "[CONTEXT]\n"
                         "record_id: %s\n"
                         "date: %s\n"
                         "title: %s\n"
                         "summary: %s\n"
                         "body: %s\n"
                         "content_truncated: %s\n"
                         "[USER QUESTION]\n%s",
                         ctx->record_key, ctx->date, ctx->title, ctx->summary,
                         ctx->body, ctx->content_truncated ? "true" : "false",
                         question);

  if (content_len < 0 || content_len >= CONFIG_VS_VOICE_PROMPT_MAX_BYTES)
    {
      free(content);
      return -EMSGSIZE;
    }

  array = cJSON_CreateArray();
  msg   = cJSON_CreateObject();
  if (array == NULL || msg == NULL)
    {
      cJSON_Delete(array); cJSON_Delete(msg); free(content);
      return -ENOMEM;
    }

  cJSON_AddStringToObject(msg, "role", "user");
  cJSON_AddStringToObject(msg, "content", content);
  cJSON_AddItemToArray(array, msg);
  free(content);

  text = cJSON_PrintUnformatted(array);
  cJSON_Delete(array);
  if (text == NULL) return -ENOMEM;

  ret = snprintf(out, out_cap, "%s", text);
  free(text);
  if (ret < 0 || (size_t)ret >= out_cap) return -EMSGSIZE;
  return ret;
}
```
可以看到 messages 数组里**只放了一条 `role: "user"` 的消息**——上下文（record 的 date/title/summary/body）和本轮问题被拼进同一条 user content 里，system prompt 是单独通过 `llm_chat()` 的第一个参数传的（不在这个 JSON 数组里）。

**`vs_voice_build_photo_prompt()`**（`vs_voice.c:553-561`，拍照问答路径）：
```c
static int vs_voice_build_photo_prompt(const char *question,
                                       char *out, size_t out_cap)
{
  int ret = snprintf(out, out_cap, "%s\n\n[USER QUESTION]\n%s",
                     VS_VOICE_SYSTEM_PROMPT, question);

  if (ret < 0 || (size_t)ret >= out_cap)
    {
      return -EMSGSIZE;
    }

  return ret;
}
```
注意这条路径直接把 `VS_VOICE_SYSTEM_PROMPT` 拼进纯文本 prompt 里传给 `llm_chat_vision_raw()`，跟 RECORD 路径（system prompt 单独传参 + user content 是 JSON messages 数组）用的是**两种不同的传参方式**——这是当前代码里 RECORD 和 PHOTO 两条路径不对称的地方，重构时要注意。

### 4.4 `VS_VOICE_SYSTEM_PROMPT` 完整文本（`vs_voice.c:417-428`）

```c
static const char VS_VOICE_SYSTEM_PROMPT[] =
  "你是 VelaSight 的闲时语音助手。\n"
  "只能依据本次请求提供的记录、照片和问题回答，不得编造记录中没有的信息。\n"
  "记录中的情绪、表情和建议都是可能的辅助线索，不得进行身份识别、人格判断、"
