/* One question/answer turn kept verbatim in RAM while a conversation is in
 * flight.  Sized generously enough for a real spoken answer (the system
 * prompt already asks the model to keep "answer" under ~150 Chinese
 * characters) without wasting the many KiB VS_VOICE_ANSWER_MAX allows for
 * the raw per-call buffer -- turns[] lives for the whole conversation, that
 * buffer only for one call. */

#define VS_VOICE_TURN_Q_MAX VS_VOICE_QUESTION_MAX
#define VS_VOICE_TURN_A_MAX 768

struct vs_voice_turn_s
{
  char question[VS_VOICE_TURN_Q_MAX];
  char answer[VS_VOICE_TURN_A_MAX];
};

/* State for one idle-assistant conversation: one or more question/answer
 * turns run back to back without the user leaving the voice pages.  Lives
 * only in RAM for the duration of the conversation; vs_voice_conv_persist()
 * writes it to CHAT history when the conversation ends, then
 * vs_voice_conv_reset() clears it.  Touched only by the single voice worker
 * thread -- vs_app.c's UI thread never reads or writes it -- so unlike
 * g_voice below it needs no lock of its own. */

struct vs_voice_conversation_s
{
  enum vs_voice_ctx_e ctx;
  char     record_key[VS_HISTORY_KEY_MAX];
  uint32_t start_ms;
  char     *summary;       /* NULL until the first compaction happens */
  struct vs_voice_turn_s turns[CONFIG_VS_VOICE_MAX_TURNS];
  unsigned int turn_count;
  size_t   turns_bytes;    /* question+answer bytes currently in turns[] */
};

