  g_index[VS_HISTORY_KIND_COUNT][CONFIG_VS_HISTORY_MAX_RECORDS];
static unsigned int g_count[VS_HISTORY_KIND_COUNT];
static unsigned int g_next_seq[VS_HISTORY_KIND_COUNT];
static bool g_ready;

