{"content":"static bool vs_history_parse_entry(enum vs_history_kind_e kind, cJSON *obj,
                                   struct vs_history_index_s *out)
{
  cJSON *item;

  memset(out, 0, sizeof(*out));
  out->kind = kind;

  item = cJSON_GetObjectItem(obj, "record_key");
  if (item == NULL || !cJSON_IsString(item) || item->valuestring[0] == '\0')
    {
      return false;
    }

  snprintf(out->record_key, sizeof(out->record_key), "%s",
           item->valuestring);

  item = cJSON_GetObjectItem(obj, "date");
  if (item != NULL && cJSON_IsString(item))
    {
      snprintf(out->date, sizeof(out->date), "%s", item->valuestring);
    }

  item = cJSON_GetObjectItem(obj, "title");
  if (item != NULL && cJSON_IsString(item))
    {
      snprintf(out->title, sizeof(out->title), "%s", item->valuestring);
    }

  item = cJSON_GetObjectItem(obj, "summary");
  if (item != NULL && cJSON_IsString(item))
    {
      snprintf(out->summary, sizeof(out->summary), "%s", item->valuestring);
    }

  item = cJSON_GetObjectItem(obj, "calm");
  out->calm = (item != NULL && cJSON_IsNumber(item)) ?
              (uint8_t)item->valueint : 0;

  item = cJSON_GetObjectItem(obj, "happy");
  out->happy = (item != NULL && cJSON_IsNumber(item)) ?
               (uint8_t)item->valueint : 0;

  item = cJSON_GetObjectItem(obj, "tense");
  out->tense = (item != NULL && cJSON_IsNumber(item)) ?
               (uint8_t)item->valueint : 0;

  item = cJSON_GetObjectItem(obj, "incomplete");
  out->incomplete = item != NULL && cJSON_IsBool(item) && cJSON_IsTrue(item);
  return true;
}

static int vs_history_load_index(enum vs_history_kind_e kind)
{
  char path[80];
  unsigned char *raw;
  FILE *f;
  long sz;
  cJSON *root;
  int i;
  int n;

  snprintf(path, sizeof(path), "%s/%s", g_history_subdir[kind],
           VS_HISTORY_INDEX_JSN);

  f = fopen(path, "r");
  if (f == NULL)
    {
      return -ENOENT;
    }

  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) < 0 ||
      fseek(f, 0, SEEK_SET) != 0 || sz == 0 || sz > VS_HISTORY_RAW_MAX)
    {
      fclose(f);
      return -EBADMSG;
    }

  raw = malloc((size_t)sz + 1);
  if (raw == NULL)
    {
      fclose(f);
      return -ENOMEM;
    }

  n = (int)fread(raw, 1, (size_t)sz, f);
  fclose(f);
  raw[n] = '\0';

  root = cJSON_Parse((const char *)raw);
  free(raw);

  if (root == NULL || !cJSON_IsArray(root))
    {
      cJSON_Delete(root);
      return -EBADMSG;
    }

  g_count[kind]    = 0;
  g_next_seq[kind] = 0;

  for (i = 0; i < cJSON_GetArraySize(root) &&
       g_count[kind] < CONFIG_VS_HISTORY_MAX_RECORDS; i++)
    {
      cJSON *obj = cJSON_GetArrayItem(root, i);
      unsigned int seq;

      if (!cJSON_IsObject(obj))
        {
          continue;
        }

      /* A corrupt individual entry is skipped, not fatal to the load. */

      if (!vs_history_parse_entry(kind, obj, &g_index[kind][g_count[kind]]))
        {
          continue;
        }

      if (sscanf(g_index[kind][g_count[kind]].record_key, "R%08u", &seq)
          == 1 && seq + 1 > g_next_seq[kind])
        {
          g_next_seq[kind] = seq + 1;
        }

      g_count[kind]++;
    }

  cJSON_Delete(root);
  return 0;
}

static cJSON *vs_history_entry_to_json(const struct vs_history_index_s *e)
{
  cJSON *obj = cJSON_CreateObject();

  if (obj == NULL)
    {
      return NULL;
    }

  cJSON_AddStringToObject(obj, "record_key", e->record_key);
  cJSON_AddStringToObject(obj, "date", e->date);
  cJSON_AddStringToObject(obj, "title", e->title);
  cJSON_AddStringToObject(obj, "summary", e->summary);
  cJSON_AddNumberToObject(obj, "calm", e->calm);
  cJSON_AddNumberToObject(obj, "happy", e->happy);
  cJSON_AddNumberToObject(obj, "tense", e->tense);
  cJSON_AddBoolToObject(obj, "incomplete", e->incomplete);
  return obj;
}

/* Write `text` to `tmp`, fsync, close, rename onto `dest`, fsync the
 * directory.  Shared by the index save and the per-record body save. */

static int vs_history_atomic_write(const char *dir, const char *tmp,
                                   const char *dest, const char *text)
{
  size_t len = strlen(text);
  int fd;
  ssize_t written;

  fd = open(tmp, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return -errno;
    }

  written = write(fd, text, len);
  if (written < 0 || (size_t)written != len || fsync(fd) < 0)
    {
      int err = errno != 0 ? -errno : -EIO;

      close(fd);
      unlink(tmp);
      return err;
    }

  if (close(fd) < 0)
    {
      int err = -errno;

      unlink(tmp);
      return err;
    }

  if (rename(tmp, dest) < 0)
    {
      int err = -errno;

      unlink(tmp);
      return err;
    }

  /* Best-effort directory fsync so the rename itself survives a power
   * cut.  Not fatal if the platform's fs does not support it. */

  fd = open(dir, O_RDONLY);
  if (fd >= 0)
    {
      fsync(fd);
      close(fd);
    }"}

{"content":"int vs_history_open(void)
{
  int ret;
  int social_ret;
  int chat_ret;

  if (g_ready)
    {
      return 0;
    }

  ret = vs_history_wait_for_store();
  if (ret < 0)
    {
      printf("vs_history: store unavailable (%d), using seed data\n", ret);
      vs_history_load_seed();
      g_ready = true;
      return ret;
    }

  mkdir("/mnt/sdnand/ai_agent", 0700);
  mkdir(VS_HISTORY_ROOT, 0700);
  mkdir(g_history_subdir[VS_HISTORY_KIND_SOCIAL], 0700);
  mkdir(g_history_subdir[VS_HISTORY_KIND_CHAT], 0700);

  social_ret = vs_history_load_index(VS_HISTORY_KIND_SOCIAL);
  if (social_ret < 0)
    {
      printf("vs_history: no usable social index (%d), seeding\n",
             social_ret);
      vs_history_load_seed();
    }
  else
    {
      printf("vs_history: loaded %u social record(s)\n",
             g_count[VS_HISTORY_KIND_SOCIAL]);
    }

  chat_ret = vs_history_load_index(VS_HISTORY_KIND_CHAT);
  if (chat_ret < 0)
    {
      printf("vs_history: no usable chat index (%d), starting empty\n",
             chat_ret);
      g_count[VS_HISTORY_KIND_CHAT]    = 0;
      g_next_seq[VS_HISTORY_KIND_CHAT] = 0;
    }
  else
    {
      printf("vs_history: loaded %u chat record(s)\n",
             g_count[VS_HISTORY_KIND_CHAT]);
    }

  g_ready = true;
  return 0;
}

unsigned int vs_history_count(enum vs_history_kind_e kind)
{
  if (kind >= VS_HISTORY_KIND_COUNT)
    {
      return 0;
    }

  return g_count[kind];
}

int vs_history_get_index(enum vs_history_kind_e kind, unsigned int i,
                         struct vs_history_index_s *out)
{
  if (out == NULL || kind >= VS_HISTORY_KIND_COUNT || i >= g_count[kind])
    {
      return -EINVAL;
    }

  *out = g_index[kind][i];
  return 0;
}

int vs_history_read_full(enum vs_history_kind_e kind, const char *record_key,
                         char *buf, size_t len)
{
  char path[80];
  FILE *f;
  long sz;
  int n;

  if (record_key == NULL || buf == NULL || len == 0 ||
      kind >= VS_HISTORY_KIND_COUNT)
    {
      return -EINVAL;
    }

  snprintf(path, sizeof(path), "%s/%s.JSN", g_history_subdir[kind],
           record_key);

  f = fopen(path, "r");
  if (f == NULL)
    {
      return -ENOENT;
    }

  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) < 0 ||
      fseek(f, 0, SEEK_SET) != 0)
    {
      fclose(f);
      return -EIO;
    }

  if (sz >= (long)len)
    {
      sz = (long)len - 1;
    }

  n = (int)fread(buf, 1, (size_t)sz, f);
  fclose(f);
  buf[n] = '\0';
  return n;
}

int vs_history_append(enum vs_history_kind_e kind,
                      struct vs_history_index_s *index,
                      const char *full_json)
{
  char path[80];
  char tmp[80];
  unsigned int seq;
  int ret;

  if (index == NULL || kind >= VS_HISTORY_KIND_COUNT)
    {
      return -EINVAL;
    }

  if (!g_ready)
    {
      return -ENODEV;
    }

  if (g_count[kind] >= CONFIG_VS_HISTORY_MAX_RECORDS)
    {
      vs_history_evict_oldest(kind);
    }

  seq = g_next_seq[kind];
  index->kind = kind;
  snprintf(index->record_key, sizeof(index->record_key), "R%08u", seq);

  if (full_json != NULL)
    {
      snprintf(path, sizeof(path), VS_HISTORY_FMT_JSN,
               g_history_subdir[kind], seq);
      snprintf(tmp, sizeof(tmp), VS_HISTORY_FMT_TMP,
               g_history_subdir[kind], seq);

      ret = vs_history_atomic_write(g_history_subdir[kind], tmp, path,
                                    full_json);
      if (ret < 0)
        {
          return ret;
        }
    }

  /* Insert at the front: index 0 is always the newest, matching how
   * vs_app.c's KEY_NEXT/KEY_BACK walk this array and how the seed data is
   * ordered. */

  memmove(&g_index[kind][1], &g_index[kind][0],
          g_count[kind] * sizeof(g_index[kind][0]));
  g_index[kind][0] = *index;
  g_count[kind]++;
  g_next_seq[kind] = seq + 1;

  ret = vs_history_save_index(kind);
  if (ret < 0)
    {
      /* The record body (if any) is already durable and simply will not be
       * listed until the next successful index save; do not lose the
       * in-memory entry over a transient write failure. */

      printf("vs_history: index save failed (%d), record %s kept in "
             "memory only\n", ret, index->record_key);
    }

  return 0;
}

void vs_history_close(void)
{
  unsigned int kind;

  g_ready = false;
  for (kind = 0; kind < VS_HISTORY_KIND_COUNT; kind++)
    {
      g_count[kind]    = 0;
      g_next_seq[kind] = 0;
    }
}
"}

{"content":"static int start_on_free_port(const struct velasight_prov_config_s *base)
{
  struct velasight_prov_config_s cfg = *base;
  int attempt;
  int ret = -1;

  for (attempt = 0; attempt < 32; attempt++)
    {
      cfg.port = g_port;
      ret = velasight_provisioning_start(&cfg);
      if (ret == 0)
        {
          return 0;
        }

      g_port = (uint16_t)(g_port + 1);
    }

  return ret;
}

static void test_lifecycle(void)
{
  struct velasight_prov_config_s cfg;

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = g_path;
  cfg.on_saved   = on_saved;

  CHECK(!velasight_provisioning_is_running(),
        "nothing is running before start");
  CHECK(velasight_provisioning_stop() == -EALREADY,
        "stopping an idle service reports -EALREADY");

  CHECK(start_on_free_port(&cfg) == 0, "the service starts");
  CHECK(velasight_provisioning_is_running(), "the service reports running");
  CHECK(velasight_provisioning_start(&cfg) == -EALREADY,
        "a second start is refused instead of leaking a listener");
  CHECK(velasight_provisioning_stop() == 0, "the service stops");
  CHECK(!velasight_provisioning_is_running(), "the service is idle again");
  CHECK(velasight_provisioning_stop() == -EALREADY,
        "a second stop reports -EALREADY");
}

static void test_stop_interrupts_client(void)
{
  struct velasight_prov_config_s cfg;
  struct sockaddr_in addr;
  struct timespec start;
  struct timespec end;
  long elapsed_ms;
  int fd;

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = g_path;
  CHECK(start_on_free_port(&cfg) == 0,
        "the service starts for an interrupted client");

  fd = socket(AF_INET, SOCK_STREAM, 0);
  CHECK(fd >= 0, "the stalled client socket opens");
  if (fd < 0)
    {
      (void)velasight_provisioning_stop();
      return;
    }

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_port = htons(g_port);
  addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
  CHECK(connect(fd, (struct sockaddr *)&addr, sizeof(addr)) == 0,
        "the stalled client connects");
  CHECK(write(fd, "POST /save HTTP/1.1\r\n", 21) == 21,
        "the stalled client sends an incomplete request");
  usleep(50000);

  clock_gettime(CLOCK_MONOTONIC, &start);
  CHECK(velasight_provisioning_stop() == 0,
        "stop interrupts an active client");
  clock_gettime(CLOCK_MONOTONIC, &end);
  elapsed_ms = (end.tv_sec - start.tv_sec) * 1000L +
               (end.tv_nsec - start.tv_nsec) / 1000000L;
  CHECK(elapsed_ms < 500,
        "stop does not wait for the client request timeout");
  close(fd);
}

static void test_connection_burst_and_stop(void)
{
  struct velasight_prov_config_s cfg;
  struct timespec start;
  struct timespec end;
  char reply[8192];
  long elapsed_ms;
  int request;

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = g_path;
  CHECK(start_on_free_port(&cfg) == 0,
        "the service starts for a browser connection burst");

  for (request = 0; request < 24; request++)
    {
      int len = http_exchange(
          "GET / HTTP/1.1\r\nHost: 192.168.10.1\r\n"
          "Connection: close\r\n\r\n", reply, sizeof(reply));

      CHECK(len > 0 && strstr(reply, "HTTP/1.1 200 OK") != NULL,
            "every short browser connection receives the form");
    }

  clock_gettime(CLOCK_MONOTONIC, &start);
  CHECK(velasight_provisioning_stop() == 0,
        "the service stops after the connection burst");
  clock_gettime(CLOCK_MONOTONIC, &end);
  elapsed_ms = (end.tv_sec - start.tv_sec) * 1000L +
               (end.tv_nsec - start.tv_nsec) / 1000000L;
  CHECK(elapsed_ms < 500,
        "connection cleanup cannot hold the network switch worker");
}

static void test_get_and_save(void)
{
  struct velasight_prov_credentials_s cred;
  struct velasight_prov_config_s cfg;
  volatile bool saw_callback = false;
  char reply[8192];
  int len;

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = g_path;
  cfg.on_saved   = on_saved;
  cfg.cb_arg     = (void *)&saw_callback;

  reset_callback();
  CHECK(start_on_free_port(&cfg) == 0, "the service starts for a submit");

  len = http_exchange("GET / HTTP/1.1\r\nHost: 192.168.10.1\r\n"
                      "Connection: close\r\n\r\n", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 200 OK") != NULL &&
        strstr(reply, "name=\"ssid\"") != NULL,
        "GET / returns the form and the peer closes");
  CHECK(cb_calls() == 0, "serving the page does not fire the callback");

  len = http_exchange("POST /save HTTP/1.1\r\nHost: 192.168.10.1\r\n"
                      "Content-Type: application/x-www-form-urlencoded\r\n"
                      "Content-Length: 30\r\n\r\n"
                      "ssid=AIPC&password=testpass123", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 200 OK") != NULL,
        "a valid submit is accepted");
  CHECK(strstr(reply, "AIPC") != NULL,
        "the success page names the network that was saved");
  CHECK(strstr(reply, "testpass123") == NULL,
        "the success page does not echo the passphrase");

  /* The response arrived and the socket closed before the callback ran; the
   * flag was set by the callback, so seeing it now proves the order rather
   * than merely that both happened.
   */

  for (len = 0; len < 200 && cb_calls() == 0; len++)
    {
      usleep(10000);
    }

  CHECK(cb_calls() == 1, "the callback fired exactly once");
  CHECK(saw_callback, "the callback ran after the response was delivered");
  CHECK(g_cb_status == 0, "the callback reported success");
  CHECK(g_cb_generation == 1, "the callback carried generation 1");
  CHECK(velasight_provisioning_generation() == 1,
        "the service exposes the same generation");

  CHECK(velasight_provisioning_load_from(g_path, &cred) == 0 &&
        strcmp(cred.ssid, "AIPC") == 0 &&
        strcmp(cred.password, "testpass123") == 0 && cred.generation == 1,
        "the credentials are on disk and readable");

  /* Still listening: the default is to stay up until the application stops
   * it, and a second submit replaces the first with a new generation.
   */

  CHECK(velasight_provisioning_is_running(),
        "the service keeps running after a save by default");

  len = http_exchange("POST /save HTTP/1.1\r\n"
                      "Content-Type: application/x-www-form-urlencoded\r\n"
                      "Content-Length: 22\r\n\r\n"
                      "ssid=OpenNet&password=", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 200 OK") != NULL,
        "an open network submit is accepted");
  for (len = 0; len < 200 && cb_calls() < 2; len++)
    {
      usleep(10000);
    }

  CHECK(cb_calls() == 2 && g_cb_generation == 2,
        "the second save produces generation 2");
  CHECK(velasight_provisioning_load_from(g_path, &cred) == 0 &&
        strcmp(cred.ssid, "OpenNet") == 0 && cred.open_network,
        "the replacement is what is stored");

  CHECK(velasight_provisioning_stop() == 0, "the service stops after saves");
}

static void test_repeated_password_save_cycles(void)
{
  struct velasight_prov_credentials_s cred;
  struct velasight_prov_config_s cfg;
  char path[sizeof(g_path) + 16];
  char reply[8192];
  int cycle;

  snprintf(path, sizeof(path), "%s.cycles", g_path);
  unlink(path);
  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = path;
  cfg.on_saved = on_saved;

  for (cycle = 0; cycle < 4; cycle++)
    {
      int wait;
      int len;

      reset_callback();
      CHECK(start_on_free_port(&cfg) == 0,
            "the service restarts for a password save cycle");
      len = http_exchange(
          "POST /save HTTP/1.1\r\n"
          "Content-Type: application/x-www-form-urlencoded\r\n"
          "Content-Length: 35\r\n\r\n"
          "ssid=CycleNet&password=cyclepass123", reply, sizeof(reply));
      CHECK(len > 0 && strstr(reply, "HTTP/1.1 200 OK") != NULL,
            "the password save cycle returns success");
      for (wait = 0; wait < 200 && cb_calls() == 0; wait++)
        {
          usleep(10000);
        }

      CHECK(cb_calls() == 1 && g_cb_status == 0,
            "the password save cycle reports persistence success");
      CHECK(velasight_provisioning_stop() == 0,
            "the service stops after a password save cycle");
    }

  CHECK(velasight_provisioning_load_from(path, &cred) == 0 &&
        strcmp(cred.ssid, "CycleNet") == 0 &&
        strcmp(cred.password, "cyclepass123") == 0 &&
        cred.generation == 4,
        "repeated password saves retain the latest valid record");
  unlink(path);
}

static void test_rejections(void)
{
  struct velasight_prov_credentials_s before;
  struct velasight_prov_credentials_s after;
  struct velasight_prov_config_s cfg;
  char reply[8192];
  int len;

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = g_path;
  cfg.on_saved   = on_saved;

  CHECK(velasight_provisioning_load_from(g_path, &before) == 0,
        "a stored record exists before the rejection tests");

  reset_callback();
  CHECK(start_on_free_port(&cfg) == 0, "the service starts for rejections");

  len = http_exchange("POST /save HTTP/1.1\r\n"
                      "Content-Type: application/x-www-form-urlencoded\r\n"
                      "Content-Length: 22\r\n\r\n"
                      "ssid=AIPC&password=abc", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 400") != NULL,
        "a 3-byte passphrase is refused with 400");

  len = http_exchange("POST /save HTTP/1.1\r\n"
                      "Content-Type: text/plain\r\n"
                      "Content-Length: 4\r\n\r\nssid", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 415") != NULL,
        "a wrong content type is refused with 415");

  len = http_exchange("GET /nope HTTP/1.1\r\n\r\n", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 404") != NULL,
        "an unknown path is refused with 404");

  len = http_exchange("PUT / HTTP/1.1\r\n\r\n", reply, sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 405") != NULL,
        "an unsupported method is refused with 405");

  CHECK(cb_calls() == 0, "no rejection fires the saved callback");
  CHECK(velasight_provisioning_load_from(g_path, &after) == 0 &&
        after.generation == before.generation &&
        strcmp(after.ssid, before.ssid) == 0,
        "a rejected submit leaves the stored record untouched");
  CHECK(velasight_provisioning_is_running(),
        "rejections do not stop the service");
  CHECK(velasight_provisioning_stop() == 0, "the service stops");
}

static void test_one_shot(void)
{
  struct velasight_prov_config_s cfg;
  char reply[8192];
  int len;

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = g_path;
  cfg.on_saved   = on_saved;
  cfg.one_shot   = true;

  reset_callback();
  CHECK(start_on_free_port(&cfg) == 0, "the one-shot service starts");

  len = http_exchange("POST /save HTTP/1.1\r\n"
                      "Content-Type: application/x-www-form-urlencoded\r\n"
                      "Content-Length: 32\r\n\r\n"
                      "ssid=OneShot&password=passphrase", reply,
                      sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 200 OK") != NULL,
        "the one-shot submit is accepted and answered");

  for (len = 0; len < 300 && velasight_provisioning_is_running(); len++)
    {
      usleep(10000);
    }

  CHECK(!velasight_provisioning_is_running(),
        "one-shot mode stops itself after a save");
  CHECK(cb_calls() == 1, "one-shot mode still notifies the application");
  CHECK(velasight_provisioning_stop() == -EALREADY,
        "stopping an already finished one-shot service is not an error");
}

static void test_store_failure_is_reported(void)
{
  struct velasight_prov_config_s cfg;
  char reply[8192];
  int len;

  /* An unwritable store is what SD-NAND being unmounted looks like from here.
   * The submit must fail loudly rather than answer 200 and lose the input.
   */

  memset(&cfg, 0, sizeof(cfg));
  cfg.store_path = "/tmp/vp_no_such_dir/x/y/rec.bin";
  cfg.on_saved   = on_saved;

  reset_callback();
  CHECK(start_on_free_port(&cfg) == 0,
        "the service starts even with an unusable store");

  len = http_exchange("POST /save HTTP/1.1\r\n"
                      "Content-Type: application/x-www-form-urlencoded\r\n"
                      "Content-Length: 31\r\n\r\n"
                      "ssid=AIPC&password=passphrase12", reply,
                      sizeof(reply));
  CHECK(len > 0 && strstr(reply, "HTTP/1.1 500") != NULL,
        "a failed write answers 500");

  for (len = 0; len < 200 && cb_calls() == 0; len++)
    {
      usleep(10000);
    }

  CHECK(cb_calls() == 1 && g_cb_status < 0,
        "the application is told the save failed");
  CHECK(velasight_provisioning_stop() == 0, "the service stops");
}

static void cleanup(void)
{
  char path[sizeof(g_path) + 8];

  snprintf(path, sizeof(path), "%s.tmp", g_path);
  unlink(path);
  unlink(g_path);
  rmdir(g_dir);
}

int main(void)
{
  int status;

  if (mkdtemp(g_dir) == NULL)
    {
      printf("FAIL cannot create a temporary directory\n");
      return 1;
    }

  snprintf(g_path, sizeof(g_path), "%s/wifi-provision.bin", g_dir);

  test_lifecycle();
  test_stop_interrupts_client();
  test_connection_burst_and_stop();
  test_get_and_save();
  test_repeated_password_save_cycles();
  test_rejections();
  test_one_shot();
  test_store_failure_is_reported();
  cleanup();

  status = g_failures == 0 ? 0 : 1;
  printf("%s: %d checks, %d failures\n",
         status == 0 ? "PASS" : "FAIL", g_checks, g_failures);
  return status;
}
"}

