  g_conv.start_ms = vs_voice_now_ms();
  if (record_key != NULL)
    {
      snprintf(g_conv.record_key, sizeof(g_conv.record_key), "%s",
               record_key);
    }

  return 0;
}

static int vs_voice_conv_append_turn(const char *question,
                                     const char *answer)
{
  struct vs_voice_turn_s *turn;

  if (question == NULL || answer == NULL || g_conv.turns == NULL)
    {
      return -EINVAL;
    }

  if (g_conv.turn_count >= CONFIG_VS_VOICE_MAX_TURNS)
    {
      return -ENOSPC;
    }

  turn = &g_conv.turns[g_conv.turn_count];
  (void)vs_voice_copy_utf8(turn->question, sizeof(turn->question), question);
  (void)vs_voice_copy_utf8(turn->answer, sizeof(turn->answer), answer);
  g_conv.context_bytes += strlen(turn->question) + strlen(turn->answer) + 32u;
  g_conv.turn_count++;
  return 0;
}

