  int ret;

  memset(&event, 0, sizeof(event));
  event.type       = type;
  event.request_id = request_id;
  event.error      = error;
  if (text != NULL)
    {
      snprintf(event.text, sizeof(event.text), "%s", text);
    }

  for (;;)
    {
      if (vs_voice_is_closing())
        {
          return;
        }

      ret = vs_app_post_event(&event);
      if (ret != -EAGAIN)
        {
          if (ret < 0)
            {
              printf("vs_voice: failed to post event %d (%d)\n", type, ret);
            }
          return;
        }

      usleep(10000);
    }
}

