#ifdef CONFIG_VS_AP_RANDOM_PASSWORD
static int vs_network_random_ap_password(char *password, size_t size)
{
  static const char alphabet[] =
    "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
  const size_t alphabet_len = sizeof(alphabet) - 1;
  uint8_t byte;
  size_t index = 0;
  int fd;
  ssize_t n;

  if (password == NULL || size < 9)
    return -EINVAL;

  fd = open("/dev/urandom", O_RDONLY);
  if (fd < 0)
    return -errno;

  while (index < 8)
    {
      n = read(fd, &byte, sizeof(byte));
      if (n != (ssize_t)sizeof(byte))
        {
          int ret = n < 0 ? -errno : -EIO;
          close(fd);
          return ret;
        }

      /* Reject the incomplete final bucket to avoid modulo bias. */
      if (byte >= (uint8_t)(256u - (256u % alphabet_len)))
        continue;

      password[index++] = alphabet[byte % alphabet_len];
    }

  password[8] = '\0';
  close(fd);
  return 0;
}
#endif

static void vs_network_provision_saved(int status, uint32_t generation,
                                       void *arg)
{
  struct vs_network_s *network = arg;

  (void)generation;
  if (network != NULL)
    {
      pthread_mutex_lock(&network->event_lock);
      network->provision_status = status;
      network->provision_event = true;
      pthread_mutex_unlock(&network->event_lock);
    }
}

static int vs_network_consume_saved(struct vs_network_s *network,
                                    bool ignore_failure)
{
  struct vs_wifi_config_s config;
  bool pending;
  int status;
  int ret;

  pthread_mutex_lock(&network->event_lock);
  pending = network->provision_event;
  status = network->provision_status;
  network->provision_event = false;
  pthread_mutex_unlock(&network->event_lock);

  if (!pending)
    return -ENOENT;

  if (status < 0)
    return ignore_failure ? -ENOENT : status;

  ret = vs_config_load_wifi(&config);
  if (ret < 0)
    return ret;

  network->config = config;
  bk7258_nand_seed_agent_config();
  return 0;
}

static int vs_network_apply_sta(struct vs_network_s *network)
{
  struct wpa_wconfig_s wifi;
  unsigned int attempt;
  int ret;

  network->status.wifi_issue = VS_WIFI_ISSUE_DISCONNECTED;
  if (network->config.sta_ssid[0] == '\0')
    return vs_network_failed(network, "STA配置", -EBADMSG);

  pthread_mutex_lock(&network->event_lock);
  network->ignore_sta_disconnect = true;
  pthread_mutex_unlock(&network->event_lock);
  ret = wapi_set_ifdown(network->sock, "wlan0");
  pthread_mutex_lock(&network->event_lock);
  network->ignore_sta_disconnect = false;
  network->wifi_event = false;
  network->sta_ipv4_ready = false;
  network->sta_disconnect_reason = 0;
  pthread_mutex_unlock(&network->event_lock);
  if (ret < 0 && ret != -ENODEV && ret != -ETIMEDOUT)
    return vs_network_failed(network, "STA关闭接口", ret);
  if (ret == -ETIMEDOUT)
    printf("velasight: STA ifdown timed out; continuing interface reset\n");

  ret = wapi_set_ifup(network->sock, "wlan0");
  if (ret < 0)
     return vs_network_failed(network, "STA开启接口", ret);

  memset(&wifi, 0, sizeof(wifi));
  wifi.ifname = "wlan0";
  wifi.sta_mode = WAPI_MODE_MANAGED;
  if (!network->config.sta_open_network &&
      network->config.sta_password[0] != '\0')
    {
      wifi.auth_wpa = IW_AUTH_WPA_VERSION_WPA2;
      wifi.cipher_mode = IW_AUTH_CIPHER_CCMP;
      wifi.alg = WPA_ALG_CCMP;
    }
  wifi.ssid = network->config.sta_ssid;
  wifi.ssidlen = strlen(wifi.ssid);
  wifi.passphrase = network->config.sta_password;
  wifi.phraselen = strlen(wifi.passphrase);

  ret = wpa_driver_wext_associate(&wifi);
  if (ret < 0)
     return vs_network_failed(network, "STA连接", ret);

  ret = vs_network_wait_sta_association(network);
  if (ret < 0)
    {
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network,
          network->status.wifi_issue == VS_WIFI_ISSUE_PASSWORD ?
          "WiFi密码错误" :
          network->status.wifi_issue == VS_WIFI_ISSUE_SSID_NOT_FOUND ?
          "SSID未扫描到" : "STA关联", ret);
    }

  ret = -ETIMEDOUT;
  for (attempt = 0; attempt < VS_DHCP_TRIES; attempt++)
    {
      ret = netlib_obtain_ipv4addr("wlan0");
      if (ret == 0)
        {
          break;
        }

      if (attempt + 1 < VS_DHCP_TRIES)
        {
          printf("velasight: STA DHCP attempt %u failed: %d, retrying\n",
                 attempt + 1, ret);
          usleep(VS_DHCP_RETRY_MS * 1000);
        }
    }

  if (ret < 0)
    {
      network->status.wifi_issue = vs_network_sta_issue(
          network, VS_WIFI_ISSUE_DISCONNECTED);
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network,
          network->status.wifi_issue == VS_WIFI_ISSUE_PASSWORD ?
          "WiFi密码错误" : "STA获取地址", ret);
    }

  network->mode = VS_NET_STA;
  network->status.mode = VS_NET_STA;
  network->status.state = VS_NET_STA_READY;
  network->status.wifi_issue = VS_WIFI_ISSUE_NONE;
  pthread_mutex_lock(&network->event_lock);
  network->sta_ipv4_ready = true;
  pthread_mutex_unlock(&network->event_lock);
  snprintf(network->status.ssid, sizeof(network->status.ssid), "%s",
           network->config.sta_ssid);
  network->status.password[0] = '\0';
  snprintf(network->status.address, sizeof(network->status.address),
           "STA READY");
  return 0;
}

static int vs_network_apply_ap(struct vs_network_s *network)
{
  struct wpa_wconfig_s wifi;
  struct in_addr address;
  struct in_addr netmask;
  struct velasight_prov_config_s provision;
  int ret;

  if (network->config.ap_channel < 1 || network->config.ap_channel > 14 ||
      network->config.ap_ssid[0] == '\0')
    return vs_network_failed(network, "AP配置", -EINVAL);

#ifdef CONFIG_VS_AP_RANDOM_PASSWORD
  ret = vs_network_random_ap_password(network->config.ap_password,
                                      sizeof(network->config.ap_password));
  if (ret < 0)
    return vs_network_failed(network, "AP随机密码", ret);
#endif

   ret = wapi_set_ifdown(network->sock, "wlan0");
   if (ret < 0 && ret != -ENODEV && ret != -ETIMEDOUT)
     return vs_network_failed(network, "AP关闭接口", ret);
   if (ret == -ETIMEDOUT)
     printf("velasight: AP ifdown timed out; continuing cleanup\n");

  ret = wapi_set_ifup(network->sock, "wlan0");
  if (ret < 0)
    return vs_network_failed(network, "AP开启接口", ret);

  memset(&wifi, 0, sizeof(wifi));
  wifi.ifname = "wlan0";
  wifi.sta_mode = WAPI_MODE_MASTER;
  if (network->config.ap_password[0] != '\0')
    {
      wifi.auth_wpa = IW_AUTH_WPA_VERSION_WPA2;
      wifi.cipher_mode = IW_AUTH_CIPHER_CCMP;
      wifi.alg = WPA_ALG_CCMP;
    }
  wifi.freq = network->config.ap_channel;
  wifi.flag = WAPI_FREQ_FIXED;
  wifi.ssid = network->config.ap_ssid;
  wifi.ssidlen = strlen(wifi.ssid);
  wifi.passphrase = network->config.ap_password;
  wifi.phraselen = strlen(wifi.passphrase);

  ret = wpa_driver_wext_associate(&wifi);
  if (ret < 0)
    {
       vs_network_failed(network, "AP启动", ret);
      goto fail;
    }

  address.s_addr = htonl(0xc0a80a01);
  netmask.s_addr = htonl(0xffffff00);
  ret = netlib_set_ipv4addr("wlan0", &address);
  if (ret < 0)
    {
       vs_network_failed(network, "AP地址", ret);
      goto fail;
    }

  ret = netlib_set_ipv4netmask("wlan0", &netmask);
  if (ret < 0)
    {
       vs_network_failed(network, "AP掩码", ret);
      goto fail;
    }

  ret = dhcpd_start("wlan0");
  if (ret < 0)
    {
       vs_network_failed(network, "AP DHCP", ret);
      goto fail;
    }

  network->dhcp_running = true;
  memset(&provision, 0, sizeof(provision));
  provision.one_shot = false;
  provision.on_saved = vs_network_provision_saved;
  provision.cb_arg = network;
  ret = velasight_provisioning_start(&provision);
  if (ret < 0)
    {
       vs_network_failed(network, "AP配网服务", ret);
      goto fail;
    }

  network->provision_running = true;

  network->mode = VS_NET_AP;
  network->status.mode = VS_NET_AP;
  network->status.state = VS_NET_AP_READY;
  network->status.wifi_issue = VS_WIFI_ISSUE_NONE;
  pthread_mutex_lock(&network->event_lock);
  network->status.ap_client_count = network->ap_client_count;
  pthread_mutex_unlock(&network->event_lock);
  snprintf(network->status.ssid, sizeof(network->status.ssid), "%s",
           network->config.ap_ssid);
  snprintf(network->status.password, sizeof(network->status.password), "%s",
           network->config.ap_password);
  printf("velasight: SoftAP ready, ssid=%s channel=%u\n",
         network->status.ssid, network->config.ap_channel);
  snprintf(network->status.address, sizeof(network->status.address),
           "192.168.10.1");
  return 0;

fail:
  (void)vs_network_stop_provisioning(network);
  (void)vs_network_stop_dhcp(network);
  (void)wapi_set_ifdown(network->sock, "wlan0");
  return ret;
}

int vs_network_open(struct vs_network_s **network)
{
  struct vs_network_s *n;
  int ret;

  if (network == NULL)
    return -EINVAL;

  n = calloc(1, sizeof(*n));
  if (n == NULL)
    return -ENOMEM;

  ret = pthread_mutex_init(&n->event_lock, NULL);
  if (ret != 0)
    {
      free(n);
      return -ret;
    }

  ret = pthread_cond_init(&n->wifi_cond, NULL);
  if (ret != 0)
    {
      pthread_mutex_destroy(&n->event_lock);
      free(n);
      return -ret;
    }

  n->sock = wapi_make_socket();
  if (n->sock < 0)
    {
      ret = n->sock;
      pthread_cond_destroy(&n->wifi_cond);
      pthread_mutex_destroy(&n->event_lock);
      free(n);
      return ret;
    }

  ret = vs_config_load_wifi(&n->config);
  if (ret < 0)
    {
      close(n->sock);
      pthread_cond_destroy(&n->wifi_cond);
      pthread_mutex_destroy(&n->event_lock);
      free(n);
      return ret;
    }

  n->mode = VS_NET_STA;
  n->status.mode = VS_NET_STA;
  n->status.state = VS_NET_DOWN;
  n->status.wifi_issue = VS_WIFI_ISSUE_DISCONNECTED;
  ret = bk7258_wifi_register_event_callback(vs_network_wifi_event, n);
  if (ret < 0)
    {
      close(n->sock);
      pthread_cond_destroy(&n->wifi_cond);
      pthread_mutex_destroy(&n->event_lock);
      free(n);
      return ret;
    }
  *network = n;
  return 0;
}

int vs_network_request_mode(struct vs_network_s *network,
                            enum vs_net_mode_e mode)
{
  int ret;

  if (network == NULL)
    return -EINVAL;

  network->status.error = 0;
  network->status.error_reason[0] = '\0';
  network->status.state = VS_NET_SWITCHING;

  if (network->mode == VS_NET_AP && mode == VS_NET_STA)
    {
      ret = vs_network_stop_provisioning(network);
      if (ret < 0)
        {
          snprintf(network->status.error_reason,
                   sizeof(network->status.error_reason),
                   "AP provisioning stop (%d)", ret);
          network->status.state = VS_NET_ERROR;
          network->status.error = ret;
          return ret;
        }

      /* stop() joins the listener, so no callback can race with this consume.
       * Apply a completed save even when manual exit won the UI race; discard
       * a failed save because the user explicitly chose to leave AP.
       */
      ret = vs_network_consume_saved(network, true);
      if (ret < 0 && ret != -ENOENT)
        {
          snprintf(network->status.error_reason,
                   sizeof(network->status.error_reason),
                   "保存WiFi配置 (%d)", ret);
          network->status.state = VS_NET_ERROR;
          network->status.error = ret;
          return ret;
        }
    }

  ret = vs_network_stop_dhcp(network);
  if (ret < 0)
    {
      snprintf(network->status.error_reason,
               sizeof(network->status.error_reason), "DHCP停止 (%d)", ret);
      network->status.state = VS_NET_ERROR;
      network->status.error = ret;
      return ret;
    }

  /* AP resources are gone before STA association begins.  If association or
   * DHCP then fails, the next network toggle must be able to enter AP again.
   */
  if (mode == VS_NET_STA)
    {
      network->mode = VS_NET_STA;
      network->status.mode = VS_NET_STA;
    }

  ret = mode == VS_NET_AP ? vs_network_apply_ap(network) :
                             vs_network_apply_sta(network);
    if (ret < 0)
      {
        if (network->status.error_reason[0] == '\0')
          snprintf(network->status.error_reason,
                   sizeof(network->status.error_reason),
                   "网络切换 (%d)", ret);
        network->status.state = VS_NET_ERROR;
      network->status.error = ret;
    }

  return ret;
}

int vs_network_process_events(struct vs_network_s *network)
{
  bool ap_client_event;
  bool sta_connected;
  bool sta_ipv4_ready;
  bool wifi_event;
  uint8_t ap_client_count;
  bool changed = false;
  int disconnect_reason;
  int ret;

  if (network == NULL)
    return 0;

  pthread_mutex_lock(&network->event_lock);
  wifi_event = network->wifi_event;
  sta_connected = network->sta_connected;
  sta_ipv4_ready = network->sta_ipv4_ready;
  disconnect_reason = network->sta_disconnect_reason;
  network->wifi_event = false;
  ap_client_event = network->ap_client_event;
  ap_client_count = network->ap_client_count;
  network->ap_client_event = false;
  pthread_mutex_unlock(&network->event_lock);

  if (network->mode == VS_NET_STA && wifi_event)
    {
      if (sta_connected)
        {
          network->status.state = sta_ipv4_ready ? VS_NET_STA_READY :
                                                   VS_NET_DOWN;
          network->status.wifi_issue = sta_ipv4_ready ?
                                       VS_WIFI_ISSUE_NONE :
                                       VS_WIFI_ISSUE_DISCONNECTED;
          if (sta_ipv4_ready)
            {
              network->status.error = 0;
              network->status.error_reason[0] = '\0';
            }
          changed = true;
        }
      else
        {
          network->status.state = VS_NET_DOWN;
          network->status.wifi_issue =
              disconnect_reason == (int)BK7258_WIFI_REASON_NO_AP_FOUND ?
              VS_WIFI_ISSUE_SSID_NOT_FOUND :
              disconnect_reason == (int)BK7258_WIFI_REASON_WRONG_PASSWORD ?
              VS_WIFI_ISSUE_PASSWORD : VS_WIFI_ISSUE_DISCONNECTED;
          changed = true;
        }
    }

  if (network->mode == VS_NET_AP && ap_client_event)
    {
      network->status.ap_client_count = ap_client_count;
      changed = true;
    }

  ret = vs_network_consume_saved(network, false);
  if (ret == -ENOENT)
    return changed ? 1 : 0;

  if (ret < 0)
    {
      network->status.error = ret;
      network->status.state = VS_NET_AP_READY;
      return ret;
    }

  /* Keep AP and the provisioning listener alive after a save.  The saved STA
   * credentials are applied only when the user explicitly exits AP mode. */
  return 1;
}

int vs_network_get_status(struct vs_network_s *network,
                          struct vs_net_status_s *status)
{
  if (network == NULL || status == NULL)
    return -EINVAL;

  *status = network->status;
  return 0;
}

void vs_network_close(struct vs_network_s *network)
{
  if (network == NULL)
    return;

  bk7258_wifi_unregister_event_callback(vs_network_wifi_event, network);
  (void)vs_network_stop_provisioning(network);
  if (vs_network_stop_dhcp(network) < 0)
    printf("velasight: DHCP server did not stop cleanly\n");

  (void)wapi_set_ifdown(network->sock, "wlan0");
  close(network->sock);
  pthread_cond_destroy(&network->wifi_cond);
  pthread_mutex_destroy(&network->event_lock);
  free(network);
}
"}

{"content":"#define VP_RESPONSE_TIMEOUT_MS 1000
#define VP_SOCKET_TIMEOUT_SEC 2
#define VP_SOCKET_LINGER_SEC 1
#define VP_STORE_PATH_MAX  192
#define VP_THREAD_STACK    8192

struct vp_server_s
{
  int       listenfd;
  int       clientfd;
  int       stoprd;
  int       stopwr;
  pthread_t thread;
  int       state;
  bool      stopping;
  bool      one_shot;
  char      store_path[VP_STORE_PATH_MAX];
  uint32_t  generation;
  velasight_prov_saved_cb_t on_saved;
  void     *cb_arg;
};

static struct vp_server_s g_server =
{
  .listenfd = -1,
  .clientfd = -1,
  .stoprd   = -1,
  .stopwr   = -1,
  .state    = VP_STATE_IDLE,
};

static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;

/* Request and response buffers are static because only one connection is
 * served at a time and 6KB of thread stack on this part is not free.
 */

static char g_request[VP_HTTP_MAX_HEADERS + VP_HTTP_MAX_BODY + 1];
static char g_response[VP_HTTP_RESPONSE_MAX];

static bool vp_stopping(void)
{
  bool stopping;

  pthread_mutex_lock(&g_lock);
  stopping = g_server.stopping;
  pthread_mutex_unlock(&g_lock);
  return stopping;
}

static int vp_wait_stop(int timeout_ms)
{
  struct pollfd pfd;
  int ret;

  pfd.fd = g_server.stoprd;
  pfd.events = POLLIN;
  pfd.revents = 0;
  do
    {
      ret = poll(&pfd, 1, timeout_ms);
    }
  while (ret < 0 && errno == EINTR);

  if (ret > 0 || vp_stopping())
    {
      return -ECANCELED;
    }

  return ret < 0 ? -errno : 0;
}

static int vp_write_all(int fd, const char *data, size_t len)
{
  size_t sent = 0;
  int waited = 0;

  while (sent < len)
    {
      int flags = MSG_DONTWAIT;
      ssize_t n;

#ifdef MSG_NOSIGNAL"}

{"content":"static void vp_handle(int fd, bool *saved, int *save_status,
                      uint32_t *generation)
{
  struct velasight_prov_credentials_s cred;
  struct vp_http_request_s req;
  size_t len = 0;
  int ret;

  *saved = false;
  *save_status = 0;

  ret = vp_read_request(fd, &req);
  if (ret < 0)
    {
      if (ret == -E2BIG)
        {
          len = vp_http_status_page(g_response, sizeof(g_response), 431,
                                    "请求过大。");
        }
      else
        {
          /* Nothing usable arrived; answering a client that already gave up
           * is not worth a second syscall.
           */

          return;
        }
    }
  else if (req.action == VP_HTTP_ACTION_PAGE)
    {
       {
         struct velasight_prov_credentials_s current;
         const char *ssid = NULL;

         if (velasight_provisioning_load(&current) == 0)
           ssid = current.ssid;
         len = vp_http_form_page_with_ssid(g_response, sizeof(g_response),
                                           NULL, ssid);
       }
    }
  else if (req.action == VP_HTTP_ACTION_REJECT)
    {
      len = vp_http_status_page(g_response, sizeof(g_response), req.status,
                               req.status == 404 ? "页面不存在。" :
                               req.status == 405 ? "不支持该请求方法。" :
                               req.status == 413 ? "提交内容过大。" :
                               req.status == 415 ? "提交格式不受支持。" :
                               req.status == 411 ? "缺少 Content-Length。" :
                                                   "请求无法解析。");
    }
  else
    {
      memset(&cred, 0, sizeof(cred));
      ret = vp_form_parse(g_request + req.header_len, req.content_length,
                          &cred);
      if (ret < 0)
        {
          /* No detail about which field failed and no echo of what was typed:
           * the notice has to be useful to the person at the phone without
           * repeating a passphrase back over an open network.
           */

           {
             struct velasight_prov_credentials_s current;
             const char *ssid = NULL;

             if (velasight_provisioning_load(&current) == 0)
               ssid = current.ssid;
             len = vp_http_form_page_with_ssid(
                 g_response, sizeof(g_response),
                 "SSID 需 1-32 字节，密码需留空或 8-63 字节，"
                 "API key 需为可打印字符，请检查后重试。", ssid);
           }
          if (len > 0)
            {
              /* Reuse the form page body but answer 400, so a client that
               * checks the status still learns the submit failed.
               */

              len = vp_http_status_page(g_response, sizeof(g_response), 400,
                                        "SSID 需 1-32 字节，密码需留空或 "
                                        "8-63 字节。");
            }
        }
        else
          {
            struct velasight_prov_credentials_s previous;
            bool have_previous = velasight_provisioning_load(&previous) == 0;

            /* None of the three secret fields are pre-filled in HTML.  An
             * ordinary Wi-Fi-only resubmit must not erase any of them. */
            if (cred.api_key[0] == '\0' && have_previous)
              {
                snprintf(cred.api_key, sizeof(cred.api_key), "%s",
                         previous.api_key);
              }

            if (cred.volc_appid[0] == '\0' && have_previous)
              {
                snprintf(cred.volc_appid, sizeof(cred.volc_appid), "%s",
                         previous.volc_appid);
              }

            if (cred.volc_token[0] == '\0' && have_previous)
              {
                snprintf(cred.volc_token, sizeof(cred.volc_token), "%s",
                         previous.volc_token);
              }

            cred.generation = vp_store_next_generation(g_server.store_path);
          ret = vp_store_save(g_server.store_path, &cred);
          if (ret < 0)
            {
              *saved = false;
              *save_status = ret;
              len = vp_http_status_page(g_response, sizeof(g_response), 500,
                                        "写入持久存储失败，凭据未保存。");
            }
          else
            {
              *saved = true;
              *save_status = 0;
              *generation = cred.generation;
              len = vp_http_saved_page(g_response, sizeof(g_response),
                                       cred.ssid, cred.generation,
                                       cred.open_network);
            }
        }
    }

  if (len > 0)
    {
      ret = vp_write_all(fd, g_response, len);
      if (ret < 0)
        {
          /* Transport failure does not undo a completed persistent save.
           * In particular, NuttX may return ENOMEM when TCP write buffers are
           * temporarily exhausted by repeated phone connections.  Report the
           * stored result to the application; only vp_store_save() decides
           * whether the credentials were saved.
           */

          printf("provision_web: response write failed: %d\n", ret);
        }
    }
}

static void *vp_thread(void *arg)
{
  (void)arg;

  for (; ; )
    {
      struct pollfd pfd[2];
      uint32_t generation = 0;
      int save_status = 0;
      bool saved = false;
      bool stopping;
      int fd;
      int ret;

      pthread_mutex_lock(&g_lock);
      stopping = g_server.stopping;
      pthread_mutex_unlock(&g_lock);
      if (stopping)
        {
          break;
        }

      pfd[0].fd = g_server.listenfd;
      pfd[0].events = POLLIN;
      pfd[0].revents = 0;
      pfd[1].fd = g_server.stoprd;
      pfd[1].events = POLLIN;
      pfd[1].revents = 0;

      /* Polling rather than blocking in accept(): stop() then needs no signal
       * and no socket shutdown trick that may or may not wake accept on a
       * given stack.
       *
       * This requires CONFIG_NET_TCPBACKLOG on NuttX, which the Kconfig
       * depends on.  Without it TCP_BACKLOG events never fire, POLLIN on a
       * listening socket is unreachable, and accept() blocks with no timeout
       * at all -- measured on the board as a service that reported
       * "listening" and then answered nothing.
       */

      ret = poll(pfd, 2, VP_ACCEPT_POLL_MS);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          break;
        }

      if (ret == 0)
        {
          continue;
        }

      if (pfd[1].revents != 0 || vp_stopping())
        {
          break;
        }

      fd = accept(g_server.listenfd, NULL, NULL);
      if (fd < 0)
        {
          if (errno == EINTR || errno == ECONNABORTED)
            {
              continue;
            }

          break;
        }

      {
        struct linger linger;
        struct timeval tv;

        tv.tv_sec = VP_SOCKET_TIMEOUT_SEC;
        tv.tv_usec = 0;
        (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
        (void)setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));

        /* NuttX otherwise leaves an active HTTP close, its send callback and
         * its close callback alive for the 120-second TIME_WAIT default.  A
         * one-second linger deadline preserves the normal graceful response
         * path, but forcibly reclaims a phone connection that never finishes
         * closing.  This is essential because callbacks are a global pool.
         */

        linger.l_onoff = 1;
        linger.l_linger = VP_SOCKET_LINGER_SEC;
        if (setsockopt(fd, SOL_SOCKET, SO_LINGER, &linger,
                       sizeof(linger)) < 0)
          {
            printf("provision_web: SO_LINGER failed: %d\n", -errno);
          }
      }

      stopping = vp_stopping();
      if (stopping)
        {
          close(fd);
          break;
        }

      pthread_mutex_lock(&g_lock);
      if (!g_server.stopping)
        {
          g_server.clientfd = fd;
        }
      pthread_mutex_unlock(&g_lock);

      printf("provision_web: accepted client\n");
      vp_handle(fd, &saved, &save_status, &generation);

       /* Close before notifying.  The application may leave SoftAP from the
        * callback, and doing that with the response still in flight is what
        * makes a successful save look like a failed submit on the phone.
       */

      pthread_mutex_lock(&g_lock);
      if (g_server.clientfd == fd)
        {
          g_server.clientfd = -1;
        }
      pthread_mutex_unlock(&g_lock);
      close(fd);

      if (saved)
        {
          pthread_mutex_lock(&g_lock);
          g_server.generation = generation;
          pthread_mutex_unlock(&g_lock);
        }

      if (saved || save_status < 0)
        {
          if (g_server.on_saved != NULL)
            {
              g_server.on_saved(save_status, generation, g_server.cb_arg);
            }
        }

      if (saved && g_server.one_shot)
        {
          break;
        }

      pthread_mutex_lock(&g_lock);
      stopping = g_server.stopping;
      pthread_mutex_unlock(&g_lock);
      if (stopping)
        {
          break;
        }
    }

  pthread_mutex_lock(&g_lock);
  if (g_server.listenfd >= 0)
    {
      close(g_server.listenfd);
      g_server.listenfd = -1;
    }

  if (g_server.stoprd >= 0)
    {
      close(g_server.stoprd);
      g_server.stoprd = -1;
    }

  g_server.state = VP_STATE_FINISHED;
  pthread_mutex_unlock(&g_lock);
  return NULL;
}

/* Caller holds g_lock. */

static void vp_reap_locked(void)
{
  if (g_server.state == VP_STATE_FINISHED)
    {
      pthread_t thread = g_server.thread;

      pthread_mutex_unlock(&g_lock);
      pthread_join(thread, NULL);
      pthread_mutex_lock(&g_lock);
      if (g_server.stopwr >= 0)
        {
          close(g_server.stopwr);
          g_server.stopwr = -1;
        }

      g_server.state = VP_STATE_IDLE;
    }
}

int velasight_provisioning_start(
    const struct velasight_prov_config_s *config)
{
  struct velasight_prov_config_s cfg;
  struct sockaddr_in addr;
  pthread_attr_t attr;
  uint16_t port;
  int stopfds[2];
  int one = 1;
  int fd;
  int ret;

  memset(&cfg, 0, sizeof(cfg));
  if (config != NULL)
    {
      cfg = *config;
    }

  if (cfg.store_path != NULL &&
      strlen(cfg.store_path) >= VP_STORE_PATH_MAX)
    {
      return -ENAMETOOLONG;
    }

  pthread_mutex_lock(&g_lock);
  vp_reap_locked();
  if (g_server.state != VP_STATE_IDLE)
    {
      pthread_mutex_unlock(&g_lock);
      return -EALREADY;
    }

  if (pipe(stopfds) < 0)
    {
      ret = -errno;
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  port = cfg.port != 0 ? cfg.port :
         (uint16_t)CONFIG_VELASIGHT_PROVISION_PORT;

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      ret = -errno;
      close(stopfds[0]);
      close(stopfds[1]);
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));

  memset(&addr, 0, sizeof(addr));
  addr.sin_family      = AF_INET;
  addr.sin_port        = htons(port);
  addr.sin_addr.s_addr = htonl(INADDR_ANY);

  if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0 ||
      listen(fd, 2) < 0)
    {
      ret = -errno;
      close(fd);
      close(stopfds[0]);
      close(stopfds[1]);
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  g_server.listenfd   = fd;
  g_server.stopping   = false;
  g_server.one_shot   = cfg.one_shot;
  g_server.generation = 0;
  g_server.on_saved   = cfg.on_saved;
  g_server.cb_arg     = cfg.cb_arg;
  g_server.stoprd     = stopfds[0];
  g_server.stopwr     = stopfds[1];
  g_server.clientfd   = -1;
  snprintf(g_server.store_path, sizeof(g_server.store_path), "%s",
           cfg.store_path != NULL ? cfg.store_path :
           CONFIG_VELASIGHT_PROVISION_STORE);
  g_server.state = VP_STATE_RUNNING;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, VP_THREAD_STACK);
  ret = pthread_create(&g_server.thread, &attr, vp_thread, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      close(fd);
      close(stopfds[0]);
      close(stopfds[1]);
      g_server.listenfd = -1;
      g_server.clientfd = -1;
      g_server.stoprd = -1;
      g_server.stopwr = -1;
      g_server.state = VP_STATE_IDLE;
      pthread_mutex_unlock(&g_lock);
      return -ret;
    }

  pthread_mutex_unlock(&g_lock);

  printf("provision_web: listening on 0.0.0.0:%u, store %s\n",
         (unsigned)port, g_server.store_path);
  return 0;
}

int velasight_provisioning_stop(void)
{
  pthread_t thread;

  pthread_mutex_lock(&g_lock);
  vp_reap_locked();
  if (g_server.state != VP_STATE_RUNNING)
    {
      pthread_mutex_unlock(&g_lock);
      return -EALREADY;
    }

  g_server.stopping = true;
  thread = g_server.thread;

  /* The stop pipe interrupts request parsing and response retries.  If the
   * request was already in close(), turn that close into an abortive close so
   * SO_LINGER cannot make the network-switch worker wait for a phone ACK. */

  if (g_server.clientfd >= 0)
    {
      struct linger linger;

      linger.l_onoff = 1;
      linger.l_linger = 0;
      (void)setsockopt(g_server.clientfd, SOL_SOCKET, SO_LINGER,
                       &linger, sizeof(linger));
    }

  if (g_server.stopwr >= 0)
    {
      char wake = 1;

      while (write(g_server.stopwr, &wake, sizeof(wake)) < 0 &&
             errno == EINTR)
        {
        }
    }

  /* Called from the saved callback, which runs on the listener thread: joining
   * ourselves would deadlock, so only ask the loop to end and let the normal
   * exit path close the socket.  A later stop() from the application reaps it.
   */

  if (pthread_equal(thread, pthread_self()))
    {
      pthread_mutex_unlock(&g_lock);
      return 0;
    }

  pthread_mutex_unlock(&g_lock);
  pthread_join(thread, NULL);

  pthread_mutex_lock(&g_lock);
  if (g_server.stopwr >= 0)
    {
      close(g_server.stopwr);
      g_server.stopwr = -1;
    }

  g_server.state = VP_STATE_IDLE;
  pthread_mutex_unlock(&g_lock);
  return 0;
}

bool velasight_provisioning_is_running(void)
{
  bool running;

  pthread_mutex_lock(&g_lock);
  running = g_server.state == VP_STATE_RUNNING;
  pthread_mutex_unlock(&g_lock);
  return running;
}

uint32_t velasight_provisioning_generation(void)
{
  uint32_t generation;

  pthread_mutex_lock(&g_lock);
  generation = g_server.generation;
  pthread_mutex_unlock(&g_lock);
  return generation;
}

int velasight_provisioning_load_from(
    const char *path, struct velasight_prov_credentials_s *out)
{
  if (path == NULL || out == NULL)
    {
      return -EINVAL;
    }

  return vp_store_load(path, out);
}

int velasight_provisioning_load(
    struct velasight_prov_credentials_s *out)
{
  char path[VP_STORE_PATH_MAX];

  pthread_mutex_lock(&g_lock);
  if (g_server.store_path[0] != '\0')
    {
      snprintf(path, sizeof(path), "%s", g_server.store_path);
    }
  else
    {
      snprintf(path, sizeof(path), "%s", CONFIG_VELASIGHT_PROVISION_STORE);
    }

  pthread_mutex_unlock(&g_lock);

  return velasight_provisioning_load_from(path, out);
}
