  if (json == NULL || reply == NULL)
    {
      free(json);
      free(reply);
      return;
    }

  memcpy(json, prefix, sizeof(prefix) - 1);
  memset(json + sizeof(prefix) - 1, 'x', payload_len);
  memcpy(json + sizeof(prefix) - 1 + payload_len, suffix,
