 * Public Functions
 ****************************************************************************/"}

{"content":"int vs_history_open(void)
{
  int first_error = 0;
  int store_ret;
  int ret;
  unsigned int kind;

  pthread_mutex_lock(&g_history_lock);
  if (g_opened)
    {
      for (kind = 0; kind < VS_HISTORY_KIND_COUNT; kind++)
        {
          if (!g_kind_ready[kind] && first_error == 0)
            {
              first_error = -ENODEV;
            }
        }

      pthread_mutex_unlock(&g_history_lock);
      return first_error;
    }
  pthread_mutex_unlock(&g_history_lock);

  store_ret = vs_history_wait_for_store();
  pthread_mutex_lock(&g_history_lock);
  if (g_opened)
    {
      pthread_mutex_unlock(&g_history_lock);
      return 0;
    }

  memset(g_kind_ready, 0, sizeof(g_kind_ready));
  memset(g_count, 0, sizeof(g_count));
  memset(g_next_seq, 0, sizeof(g_next_seq));

  ret = vs_history_alloc_tables_locked();
  if (ret < 0)
    {
      pthread_mutex_unlock(&g_history_lock);
      return ret;
    }

  if (store_ret < 0)
    {
      printf("vs_history: store unavailable (%d); samples are RAM-only\n",
             store_ret);
      vs_history_load_seed_memory_locked();
      g_opened = true;
      pthread_mutex_unlock(&g_history_lock);
      return store_ret;
    }

  ret = vs_history_mkdir("/mnt/sdnand/ai_agent");
  if (ret == 0)
    {
      ret = vs_history_mkdir(VS_HISTORY_ROOT);
    }

  for (kind = 0; ret == 0 && kind < VS_HISTORY_KIND_COUNT; kind++)
    {
      ret = vs_history_mkdir(g_history_dir[kind]);
    }

  if (ret < 0)
    {
      vs_history_load_seed_memory_locked();
      g_opened = true;
      pthread_mutex_unlock(&g_history_lock);
      return ret;
    }

  for (kind = 0; kind < VS_HISTORY_KIND_COUNT; kind++)
    {
      ret = vs_history_load_index_locked((enum vs_history_kind_e)kind);
      if (ret == -ENOENT)
        {
          ret = kind == VS_HISTORY_KIND_SOCIAL ?
                vs_history_seed_social_locked() :
                vs_history_create_empty_locked((enum vs_history_kind_e)kind);
        }

      if (ret == 0)
        {
          g_kind_ready[kind] = true;
          printf("vs_history: loaded %u %s record(s)\n", g_count[kind],
                 kind == VS_HISTORY_KIND_SOCIAL ? "social" : "chat");
        }
      else
        {
          /* Never replace a corrupt index with samples/empty data. */

          printf("vs_history: %s store unavailable (%d)\n",
                 kind == VS_HISTORY_KIND_SOCIAL ? "social" : "chat", ret);
          g_count[kind] = 0;
          g_next_seq[kind] = 0;
          if (first_error == 0)
            {
              first_error = ret;
            }
        }
    }

  g_opened = true;
  pthread_mutex_unlock(&g_history_lock);
  return first_error;
}"}

{"content":"int vs_history_open_full(enum vs_history_kind_e kind, const char *record_key,
                         int *fd_out, size_t *size_out)
{
  char path[VS_HISTORY_PATH_MAX];
  struct stat st;
  unsigned int seq;
  int fd;
  int ret;

  if (!vs_history_kind_valid(kind) || fd_out == NULL || size_out == NULL ||
      vs_history_key_parse(record_key, &seq) < 0)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_history_lock);
  if (!g_kind_ready[kind])
    {
      pthread_mutex_unlock(&g_history_lock);
      return -ENODEV;
    }

  ret = vs_history_find_key_locked(kind, record_key);
  if (ret < 0)
    {
      pthread_mutex_unlock(&g_history_lock);
      return ret;
    }

  vs_history_body_path(kind, seq, false, path, sizeof(path));
  fd = open(path, O_RDONLY);
  if (fd < 0)
    {
      ret = -errno;
      pthread_mutex_unlock(&g_history_lock);
      return ret;
    }

  if (fstat(fd, &st) < 0 || st.st_size <= 0 ||
      (uint64_t)st.st_size > (uint64_t)SIZE_MAX)
    {
      ret = errno != 0 ? -errno : -EIO;
      close(fd);
      pthread_mutex_unlock(&g_history_lock);
      return ret;
    }

  *fd_out = fd;
  *size_out = (size_t)st.st_size;
  pthread_mutex_unlock(&g_history_lock);
  return 0;
}

int vs_history_read_full(enum vs_history_kind_e kind, const char *record_key,
                         char *buf, size_t len)
{
  size_t size;
  int fd;
  int ret;

  if (buf == NULL || len == 0)
    {
      return -EINVAL;
    }

  ret = vs_history_open_full(kind, record_key, &fd, &size);
  if (ret < 0)
    {
      return ret;
    }

  if (size >= len)
    {
      close(fd);
      return -E2BIG;
    }

  if (size > INT_MAX)
    {
      close(fd);
      return -EFBIG;
    }

  ret = vs_history_read_all(fd, buf, size);
  close(fd);
  if (ret < 0)
    {
      return ret;
    }

  buf[size] = '\0';
  return (int)size;
}

int vs_history_append(enum vs_history_kind_e kind,
                      struct vs_history_index_s *index,
                      const char *full_json)
{
  struct vs_history_index_s *candidate;
  struct vs_history_index_s entry;
  char temporary[VS_HISTORY_PATH_MAX];
  char destination[VS_HISTORY_PATH_MAX];
  char evicted_path[VS_HISTORY_PATH_MAX];
  cJSON *body;
  unsigned int old_count;
  unsigned int new_count;
  unsigned int copy_count;
  unsigned int seq = 0;
  bool evict;
  int ret;

  if (!vs_history_kind_valid(kind) || index == NULL || full_json == NULL ||
      full_json[0] == '\0')
    {
      return -EINVAL;
    }

  body = cJSON_Parse(full_json);
  if (body == NULL || !cJSON_IsObject(body))
    {
      cJSON_Delete(body);
      return -EBADMSG;
    }
  cJSON_Delete(body);

  candidate = malloc(CONFIG_VS_HISTORY_MAX_RECORDS * sizeof(*candidate));
  if (candidate == NULL)
    {
      return -ENOMEM;
    }

  pthread_mutex_lock(&g_history_lock);
  if (!g_kind_ready[kind])
    {
      ret = -ENODEV;
      goto out_unlock;
    }

  ret = vs_history_choose_seq_locked(kind, &seq);
  if (ret < 0)
    {
      goto out_unlock;
    }

  entry = *index;
  vs_history_normalize_entry(&entry, kind, seq);

  old_count = g_count[kind];
  evict = old_count >= CONFIG_VS_HISTORY_MAX_RECORDS;
  new_count = evict ? CONFIG_VS_HISTORY_MAX_RECORDS : old_count + 1u;
  copy_count = new_count - 1u;
  candidate[0] = entry;
  if (copy_count > 0)
    {
      memcpy(&candidate[1], g_index[kind],
             copy_count * sizeof(candidate[0]));
    }

  evicted_path[0] = '\0';
  if (evict)
    {
      unsigned int evicted_seq;

      if (vs_history_key_parse(g_index[kind][old_count - 1u].record_key,
                               &evicted_seq) == 0)
        {
          vs_history_body_path(kind, evicted_seq, false, evicted_path,
                               sizeof(evicted_path));
        }
    }

  vs_history_body_path(kind, seq, true, temporary, sizeof(temporary));
  vs_history_body_path(kind, seq, false, destination, sizeof(destination));
  ret = vs_history_atomic_write(g_history_dir[kind], temporary, destination,
                                full_json);
  if (ret < 0)
    {
      goto out_unlock;
    }

  ret = vs_history_write_index_locked(kind, candidate, new_count);
  if (ret < 0)
    {
      unlink(destination);
      vs_history_sync_dir(g_history_dir[kind]);
      goto out_unlock;
    }

  memcpy(g_index[kind], candidate, new_count * sizeof(candidate[0]));
  g_count[kind] = new_count;
  g_next_seq[kind] = seq == VS_HISTORY_SEQ_MAX ? 0 : seq + 1u;
  *index = entry;

  if (evicted_path[0] != '\0' && unlink(evicted_path) < 0 && errno != ENOENT)
    {
      /* The committed index is authoritative; a failed cleanup is only an
       * orphan and must not turn a durable append into a reported failure.
       */

      printf("vs_history: could not remove evicted body %s: %d\n",
             evicted_path, -errno);
    }
  else if (evicted_path[0] != '\0')
    {
      vs_history_sync_dir(g_history_dir[kind]);
    }

  ret = 0;

out_unlock:
  pthread_mutex_unlock(&g_history_lock);
  free(candidate);
  return ret;
}"}

{"content":"static void vs_network_provision_saved(int status, uint32_t generation,
                                       void *arg)
{
  struct vs_network_s *network = arg;

  (void)generation;
  if (network != NULL)
    {
      pthread_mutex_lock(&network->event_lock);
      network->provision_status = status;
      network->provision_event = true;
      pthread_mutex_unlock(&network->event_lock);
    }
}

static int vs_network_social_history_snapshot(
    unsigned int offset, struct velasight_prov_history_entry_s *out,
    size_t capacity, unsigned int *total, unsigned int *copied, void *arg)
{
  struct vs_history_index_s *native = NULL;
  unsigned int i;
  int ret;

  (void)arg;
  if (total == NULL || copied == NULL ||
      (capacity > 0 && out == NULL) ||
      capacity > VELASIGHT_PROV_HISTORY_MAX_ENTRIES)
    {
      return -EINVAL;
    }

  if (!vs_history_is_ready(VS_HISTORY_KIND_SOCIAL))
    {
      return -ENODEV;
    }

  if (capacity > 0)
    {
      native = calloc(capacity, sizeof(*native));
      if (native == NULL)
        {
          return -ENOMEM;
        }
    }

  ret = vs_history_snapshot(VS_HISTORY_KIND_SOCIAL, offset, native, capacity,
                            total, copied);
  if (ret < 0)
    {
      free(native);
      return ret;
    }

  for (i = 0; i < *copied; i++)
    {
      if (strlen(native[i].record_key) >
          VELASIGHT_PROV_HISTORY_KEY_MAX)
        {
          free(native);
          return -EBADMSG;
        }

      snprintf(out[i].record_key, sizeof(out[i].record_key), "%s",
               native[i].record_key);
      snprintf(out[i].date, sizeof(out[i].date), "%s", native[i].date);
      snprintf(out[i].title, sizeof(out[i].title), "%s", native[i].title);
      snprintf(out[i].summary, sizeof(out[i].summary), "%s",
               native[i].summary);
      out[i].calm = native[i].calm;
      out[i].happy = native[i].happy;
      out[i].tense = native[i].tense;
      out[i].incomplete = native[i].incomplete;
    }

  free(native);
  return 0;
}

static int vs_network_social_history_open(const char *record_key, int *fd,
                                          size_t *size, void *arg)
{
  (void)arg;
  return vs_history_open_full(VS_HISTORY_KIND_SOCIAL, record_key, fd, size);
}

static int vs_network_start_provisioning(struct vs_network_s *network)
{
  struct velasight_prov_config_s provision;
  int ret;

  memset(&provision, 0, sizeof(provision));
  provision.one_shot = false;
  provision.on_saved = vs_network_provision_saved;
  provision.cb_arg = network;
  provision.history.snapshot = vs_network_social_history_snapshot;
  provision.history.open = vs_network_social_history_open;
  ret = velasight_provisioning_start(&provision);
  if (ret == 0)
    {
      network->provision_running = true;
    }

  return ret;
}

static int vs_network_consume_saved(struct vs_network_s *network,
                                    bool ignore_failure)
{
  struct vs_wifi_config_s config;
  bool pending;
  int status;
  int ret;

  pthread_mutex_lock(&network->event_lock);
  pending = network->provision_event;
  status = network->provision_status;
  network->provision_event = false;
  pthread_mutex_unlock(&network->event_lock);

  if (!pending)
    return -ENOENT;

  if (status < 0)
    return ignore_failure ? -ENOENT : status;

  ret = vs_config_load_wifi(&config);
  if (ret < 0)
    return ret;

  network->config = config;
  bk7258_nand_seed_agent_config();
  return 0;
}"}

{"content":"static int vs_network_apply_sta(struct vs_network_s *network)
{
  struct wpa_wconfig_s wifi;
  struct in_addr address;
  unsigned int attempt;
  int ret;

  network->status.wifi_issue = VS_WIFI_ISSUE_DISCONNECTED;
  if (network->config.sta_ssid[0] == '\0')
    return vs_network_failed(network, "STA配置", -EBADMSG);

  pthread_mutex_lock(&network->event_lock);
  network->ignore_sta_disconnect = true;
  pthread_mutex_unlock(&network->event_lock);
  ret = wapi_set_ifdown(network->sock, "wlan0");
  pthread_mutex_lock(&network->event_lock);
  network->ignore_sta_disconnect = false;
  network->wifi_event = false;
  network->sta_ipv4_ready = false;
  network->sta_disconnect_reason = 0;
  pthread_mutex_unlock(&network->event_lock);
  if (ret < 0 && ret != -ENODEV && ret != -ETIMEDOUT)
    return vs_network_failed(network, "STA关闭接口", ret);
  if (ret == -ETIMEDOUT)
    printf("velasight: STA ifdown timed out; continuing interface reset\n");

  ret = wapi_set_ifup(network->sock, "wlan0");
  if (ret < 0)
     return vs_network_failed(network, "STA开启接口", ret);

  memset(&wifi, 0, sizeof(wifi));
  wifi.ifname = "wlan0";
  wifi.sta_mode = WAPI_MODE_MANAGED;
  if (!network->config.sta_open_network &&
      network->config.sta_password[0] != '\0')
    {
      wifi.auth_wpa = IW_AUTH_WPA_VERSION_WPA2;
      wifi.cipher_mode = IW_AUTH_CIPHER_CCMP;
      wifi.alg = WPA_ALG_CCMP;
    }
  wifi.ssid = network->config.sta_ssid;
  wifi.ssidlen = strlen(wifi.ssid);
  wifi.passphrase = network->config.sta_password;
  wifi.phraselen = strlen(wifi.passphrase);

  ret = wpa_driver_wext_associate(&wifi);
  if (ret < 0)
     return vs_network_failed(network, "STA连接", ret);

  ret = vs_network_wait_sta_association(network);
  if (ret < 0)
    {
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network,
          network->status.wifi_issue == VS_WIFI_ISSUE_PASSWORD ?
          "WiFi密码错误" :
          network->status.wifi_issue == VS_WIFI_ISSUE_SSID_NOT_FOUND ?
          "SSID未扫描到" : "STA关联", ret);
    }

  ret = -ETIMEDOUT;
  for (attempt = 0; attempt < VS_DHCP_TRIES; attempt++)
    {
      ret = netlib_obtain_ipv4addr("wlan0");
      if (ret == 0)
        {
          break;
        }

      if (attempt + 1 < VS_DHCP_TRIES)
        {
          printf("velasight: STA DHCP attempt %u failed: %d, retrying\n",
                 attempt + 1, ret);
          usleep(VS_DHCP_RETRY_MS * 1000);
        }
    }

  if (ret < 0)
    {
      network->status.wifi_issue = vs_network_sta_issue(
          network, VS_WIFI_ISSUE_DISCONNECTED);
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network,
          network->status.wifi_issue == VS_WIFI_ISSUE_PASSWORD ?
          "WiFi密码错误" : "STA获取地址", ret);
    }

  memset(&address, 0, sizeof(address));
  ret = netlib_get_ipv4addr("wlan0", &address);
  if (ret < 0 || address.s_addr == htonl(INADDR_ANY))
    {
      if (ret >= 0)
        {
          ret = -EADDRNOTAVAIL;
        }
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network, "STA读取地址", ret);
    }

  if (inet_ntop(AF_INET, &address, network->status.address,
                sizeof(network->status.address)) == NULL)
    {
      ret = errno != 0 ? -errno : -EIO;
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network, "STA地址格式", ret);
    }

  ret = vs_network_start_provisioning(network);
  if (ret < 0)
    {
      (void)wapi_set_ifdown(network->sock, "wlan0");
      return vs_network_failed(network, "STA配网服务", ret);
    }

  network->mode = VS_NET_STA;
  network->status.mode = VS_NET_STA;
  network->status.state = VS_NET_STA_READY;
  network->status.wifi_issue = VS_WIFI_ISSUE_NONE;
  pthread_mutex_lock(&network->event_lock);
  network->sta_ipv4_ready = true;
  pthread_mutex_unlock(&network->event_lock);
  snprintf(network->status.ssid, sizeof(network->status.ssid), "%s",
           network->config.sta_ssid);
  network->status.password[0] = '\0';
  printf("velasight: STA ready, web http://%s/\n",
         network->status.address);
  return 0;
}

static int vs_network_apply_ap(struct vs_network_s *network)
{
  struct wpa_wconfig_s wifi;
  struct in_addr address;
  struct in_addr netmask;
  int ret;

  if (network->config.ap_channel < 1 || network->config.ap_channel > 14 ||
      network->config.ap_ssid[0] == '\0')
    return vs_network_failed(network, "AP配置", -EINVAL);

#ifdef CONFIG_VS_AP_RANDOM_PASSWORD
  ret = vs_network_random_ap_password(network->config.ap_password,
                                      sizeof(network->config.ap_password));
  if (ret < 0)
    return vs_network_failed(network, "AP随机密码", ret);
#endif

   ret = wapi_set_ifdown(network->sock, "wlan0");
   if (ret < 0 && ret != -ENODEV && ret != -ETIMEDOUT)
     return vs_network_failed(network, "AP关闭接口", ret);
   if (ret == -ETIMEDOUT)
     printf("velasight: AP ifdown timed out; continuing cleanup\n");

  ret = wapi_set_ifup(network->sock, "wlan0");
  if (ret < 0)
    return vs_network_failed(network, "AP开启接口", ret);

  memset(&wifi, 0, sizeof(wifi));
  wifi.ifname = "wlan0";
  wifi.sta_mode = WAPI_MODE_MASTER;
  if (network->config.ap_password[0] != '\0')
    {
      wifi.auth_wpa = IW_AUTH_WPA_VERSION_WPA2;
      wifi.cipher_mode = IW_AUTH_CIPHER_CCMP;
      wifi.alg = WPA_ALG_CCMP;
    }
  wifi.freq = network->config.ap_channel;
  wifi.flag = WAPI_FREQ_FIXED;
  wifi.ssid = network->config.ap_ssid;
  wifi.ssidlen = strlen(wifi.ssid);
  wifi.passphrase = network->config.ap_password;
  wifi.phraselen = strlen(wifi.passphrase);

  ret = wpa_driver_wext_associate(&wifi);
  if (ret < 0)
    {
       vs_network_failed(network, "AP启动", ret);
      goto fail;
    }

  address.s_addr = htonl(0xc0a80a01);
  netmask.s_addr = htonl(0xffffff00);
  ret = netlib_set_ipv4addr("wlan0", &address);
  if (ret < 0)
    {
       vs_network_failed(network, "AP地址", ret);
      goto fail;
    }

  ret = netlib_set_ipv4netmask("wlan0", &netmask);
  if (ret < 0)
    {
       vs_network_failed(network, "AP掩码", ret);
      goto fail;
    }

  ret = dhcpd_start("wlan0");
  if (ret < 0)
    {
       vs_network_failed(network, "AP DHCP", ret);
      goto fail;
    }

  network->dhcp_running = true;
  ret = vs_network_start_provisioning(network);
  if (ret < 0)
    {
       vs_network_failed(network, "AP配网服务", ret);
      goto fail;
    }

  network->mode = VS_NET_AP;
  network->status.mode = VS_NET_AP;
  network->status.state = VS_NET_AP_READY;
  network->status.wifi_issue = VS_WIFI_ISSUE_NONE;
  pthread_mutex_lock(&network->event_lock);
  network->status.ap_client_count = network->ap_client_count;
  pthread_mutex_unlock(&network->event_lock);
  snprintf(network->status.ssid, sizeof(network->status.ssid), "%s",
           network->config.ap_ssid);
  snprintf(network->status.password, sizeof(network->status.password), "%s",
           network->config.ap_password);
  printf("velasight: SoftAP ready, ssid=%s channel=%u\n",
         network->status.ssid, network->config.ap_channel);
  snprintf(network->status.address, sizeof(network->status.address),
           "192.168.10.1");
  return 0;

fail:
  (void)vs_network_stop_provisioning(network);
  (void)vs_network_stop_dhcp(network);
  (void)wapi_set_ifdown(network->sock, "wlan0");
  return ret;
}"}

{"content":"static int vp_write_all(int fd, const char *data, size_t len)
{
  size_t sent = 0;
  int waited = 0;

  while (sent < len)
    {
      int flags = MSG_DONTWAIT;
      ssize_t n;

#ifdef MSG_NOSIGNAL
      flags |= MSG_NOSIGNAL;
#endif
      n = send(fd, data + sent, len - sent, flags);

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          /* NuttX's buffered TCP send returns ENOMEM when the global socket
           * callback pool is momentarily busy, and EAGAIN/ENOBUFS when the
           * WRB or IOB pool is busy.  Phone browsers create short connection
           * bursts, so give completed closes a bounded chance to release
           * those resources.  The stop pipe makes this retry immediately
           * interruptible when the application leaves SoftAP.
           */

          if ((errno == ENOMEM || errno == EAGAIN || errno == ENOBUFS) &&
              waited < VP_RESPONSE_TIMEOUT_MS)
            {
              int ret = vp_wait_stop(VP_RESPONSE_RETRY_MS);

              if (ret < 0)
                {
                  return ret;
                }

              waited += VP_RESPONSE_RETRY_MS;
              continue;
            }

          return -errno;
        }

      if (n == 0)
        {
          return -EPIPE;"}

{"content":"static int vp_history_snapshot(
    struct velasight_prov_history_entry_s **entries_out,
    unsigned int *count_out)
{
  struct velasight_prov_history_entry_s *entries = NULL;
  unsigned int total = 0;
  unsigned int copied = 0;
  unsigned int attempt;
  int ret;

  if (entries_out == NULL || count_out == NULL || !vp_history_enabled())
    {
      return -ENODEV;
    }

  *entries_out = NULL;
  *count_out = 0;
  ret = g_server.history.snapshot(0, NULL, 0, &total, &copied,
                                  g_server.history.arg);
  if (ret < 0)
    {
      return ret;
    }

  for (attempt = 0; attempt < 2; attempt++)
    {
      unsigned int current_total = 0;

      if (total > VELASIGHT_PROV_HISTORY_MAX_ENTRIES)
        {
          return -E2BIG;
        }

      if (total == 0)
        {
          return 0;
        }

      entries = calloc(total, sizeof(*entries));
      if (entries == NULL)
        {
          return -ENOMEM;
        }

      copied = 0;
      ret = g_server.history.snapshot(0, entries, total, &current_total,
                                      &copied, g_server.history.arg);
      if (ret < 0)
        {
          free(entries);
          return ret;
        }

      if (copied > total)
        {
          free(entries);
          return -EBADMSG;
        }

      if (current_total <= total)
        {
          *entries_out = entries;
          *count_out = copied;
          return 0;
        }

      free(entries);
      entries = NULL;
      total = current_total;
    }

  return -EAGAIN;
}

static int vp_send_history_list(int fd)
{
  struct velasight_prov_history_entry_s *entries = NULL;
  unsigned int count = 0;
  unsigned int i;
  size_t body_length = 0;
  size_t len;
  int status;
  int ret;

  if (!vp_history_enabled())
    {
      return vp_send_status(fd, 404, "历史记录功能未启用。");
    }

  ret = vp_history_snapshot(&entries, &count);
  if (ret < 0)
    {
      status = vp_history_error_status(ret);
      return vp_send_status(fd, status,
                            status == 503 ? "历史存储暂不可用。" :
                            status == 404 ? "历史记录不存在。" :
                                            "读取历史记录失败。");
    }

  len = vp_http_history_head_fragment(g_response, sizeof(g_response), count);
  if (len == 0)
    {
      free(entries);
      return vp_send_status(fd, 500, "生成历史页面失败。");
    }
  body_length = len;

  for (i = 0; i < count; i++)
    {
      len = vp_http_history_entry_fragment(g_response, sizeof(g_response),
                                           &entries[i]);
      if (len == 0 || body_length > SIZE_MAX - len)
        {
          free(entries);
          return vp_send_status(fd, 500, "历史索引格式无效。");
        }

      body_length += len;
    }

  len = vp_http_history_tail_fragment(g_response, sizeof(g_response));
  if (len == 0 || body_length > SIZE_MAX - len)
    {
      free(entries);
      return vp_send_status(fd, 500, "生成历史页面失败。");
    }
  body_length += len;

  len = vp_http_response_header(g_response, sizeof(g_response), 200,
                                "text/html; charset=utf-8", body_length,
                                NULL, NULL);
  if (len == 0)
    {
      free(entries);
      return -EOVERFLOW;
    }

  ret = vp_write_all(fd, g_response, len);
  if (ret == 0)
    {
      len = vp_http_history_head_fragment(g_response, sizeof(g_response),
                                          count);
      ret = len == 0 ? -EOVERFLOW : vp_write_all(fd, g_response, len);
    }

  for (i = 0; ret == 0 && i < count; i++)
    {
      len = vp_http_history_entry_fragment(g_response, sizeof(g_response),
                                           &entries[i]);
      ret = len == 0 ? -EBADMSG : vp_write_all(fd, g_response, len);
    }

  if (ret == 0)
    {
      len = vp_http_history_tail_fragment(g_response, sizeof(g_response));
      ret = len == 0 ? -EOVERFLOW : vp_write_all(fd, g_response, len);
    }

  free(entries);
  return ret;
}

static int vp_send_history_file(int fd, const char *record_key,
                                bool download)
{
  size_t remaining;
  size_t size = 0;
  size_t len;
  int history_fd = -1;
  int status;
  int ret;

  if (!vp_history_enabled())
    {
      return vp_send_status(fd, 404, "历史记录功能未启用。");
    }

  ret = g_server.history.open(record_key, &history_fd, &size,
                              g_server.history.arg);
  if (ret < 0 || history_fd < 0)
    {
      if (history_fd >= 0)
        {
          close(history_fd);
        }

      if (ret >= 0)
        {
          ret = -EBADMSG;
        }
      status = vp_history_error_status(ret);
      return vp_send_status(fd, status,
                            status == 503 ? "历史存储暂不可用。" :
                            status == 404 ? "历史记录不存在。" :
                                            "打开历史记录失败。");
    }

  len = vp_http_response_header(
      g_response, sizeof(g_response), 200,
      download ? "application/json" : "application/json; charset=utf-8",
      size, download ? "attachment" : NULL,
      download ? record_key : NULL);
  if (len == 0)
    {
      close(history_fd);
      return -EOVERFLOW;
    }

  ret = vp_write_all(fd, g_response, len);
  remaining = size;
  while (ret == 0 && remaining > 0)
    {
      size_t wanted = remaining < sizeof(g_response) ? remaining :
                                                       sizeof(g_response);
      ssize_t n = read(history_fd, g_response, wanted);

      if (n < 0 && errno == EINTR)
        {
          continue;
        }

      if (n <= 0)
        {
          ret = n < 0 ? -errno : -EIO;
          break;
        }

      ret = vp_write_all(fd, g_response, (size_t)n);
      remaining -= (size_t)n;
    }

  close(history_fd);
  return ret;
}

/****************************************************************************
 * Name: vp_handle
 *
 * Description:
 *   Serve one connection.  Sets *saved when credentials were persisted and
 *   *save_status to 0 or the negative errno of a failed save, so the caller can
 *   notify the application only after the socket is gone.
 *
 ****************************************************************************/"}

{"content":"/****************************************************************************
 * app/provisioning_web/include/velasight_provisioning.h
 *
 * HTTP provisioning and local-history entry.  The application owns the Wi-Fi
 * role and may keep this listener on either its temporary SoftAP or an
 * already-connected STA interface.  The service binds INADDR_ANY but never
 * associates, runs DHCP, or switches radio mode itself.
 *
 * The service is unauthenticated HTTP.  Applications exposing it on STA must
 * rely on the trusted LAN boundary or add a stronger access-control layer;
 * history and credential changes are available to every client that can
 * reach the configured port.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __APP_PROVISIONING_WEB_INCLUDE_VELASIGHT_PROVISIONING_H
#define __APP_PROVISIONING_WEB_INCLUDE_VELASIGHT_PROVISIONING_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C"
{
#endif

/* IEEE 802.11 SSID length, and the WPA2 passphrase range.  An empty password
 * means an open network, which is the only reason 0 is legal.
 */

#define VELASIGHT_PROV_SSID_MAX 32
#define VELASIGHT_PROV_PSK_MIN  8
#define VELASIGHT_PROV_PSK_MAX  63
#define VELASIGHT_PROV_API_KEY_MAX 512

/* Volcengine (ByteDance speech platform) credentials for the idle voice
 * assistant's ASR and TTS.  Both fields are required together: the backend
 * refuses to open a session unless app_id and token are both non-empty (see
 * volc_asr_stream_open()/volc_tts_ws_synthesize_stream() in
 * packages/ai_agent).  Sized from what the platform actually issues, not
 * from the MiMo key's budget -- app_id is a short numeric string and token
 * is a bearer token, neither approaching 512 bytes.
 */

#define VELASIGHT_PROV_VOLC_APPID_MAX 64
#define VELASIGHT_PROV_VOLC_TOKEN_MAX 128

/* Where the record lives when the caller passes no path.  On SD-NAND, so it
 * survives a reset; /mnt itself is pseudo-filesystem and /mnt/ram is a PSRAM
 * ramdisk, neither of which would.
 *
 * Every component fits 8.3 because that SD-NAND is VFAT without long-name
 * support (CONFIG_FAT_LFN is not set). This single file contains Wi-Fi
 * credentials and the MiMo API key; deprecated KVDB is not used.
 */

#ifndef CONFIG_VELASIGHT_PROVISION_STORE
#  define CONFIG_VELASIGHT_PROVISION_STORE "/mnt/sdnand/prov/vela.cfg"
#endif

#ifndef CONFIG_VELASIGHT_PROVISION_PORT
#  define CONFIG_VELASIGHT_PROVISION_PORT 80
#endif

struct velasight_prov_credentials_s
{
  char     ssid[VELASIGHT_PROV_SSID_MAX + 1];
  char     password[VELASIGHT_PROV_PSK_MAX + 1];
  char     api_key[VELASIGHT_PROV_API_KEY_MAX + 1];
  char     volc_appid[VELASIGHT_PROV_VOLC_APPID_MAX + 1];
  char     volc_token[VELASIGHT_PROV_VOLC_TOKEN_MAX + 1];
  uint32_t generation;   /* Monotonic save counter, first save is 1 */
  bool     open_network; /* Password is empty */
};

/* Optional read-only history provider.  The HTTP core deliberately owns no
 * VelaSight storage types: a product adapter supplies compact index entries
 * and opens one stable full-record descriptor for streaming. */

#define VELASIGHT_PROV_HISTORY_KEY_MAX      8
#define VELASIGHT_PROV_HISTORY_DATE_MAX     39
#define VELASIGHT_PROV_HISTORY_TITLE_MAX    39
#define VELASIGHT_PROV_HISTORY_SUMMARY_MAX 127
#define VELASIGHT_PROV_HISTORY_MAX_ENTRIES 256

struct velasight_prov_history_entry_s
{
  char    record_key[VELASIGHT_PROV_HISTORY_KEY_MAX + 1];
  char    date[VELASIGHT_PROV_HISTORY_DATE_MAX + 1];
  char    title[VELASIGHT_PROV_HISTORY_TITLE_MAX + 1];
  char    summary[VELASIGHT_PROV_HISTORY_SUMMARY_MAX + 1];
  uint8_t calm;
  uint8_t happy;
  uint8_t tense;
  bool    incomplete;
};

typedef int (*velasight_prov_history_snapshot_cb_t)(
    unsigned int offset, struct velasight_prov_history_entry_s *out,
    size_t capacity, unsigned int *total, unsigned int *copied, void *arg);

typedef int (*velasight_prov_history_open_cb_t)(
    const char *record_key, int *fd, size_t *size, void *arg);

struct velasight_prov_history_provider_s
{
  velasight_prov_history_snapshot_cb_t snapshot;
  velasight_prov_history_open_cb_t     open;
  void                                *arg;
};

/* Called after the success page has been written and the connection closed,
 * never before.  The application may leave SoftAP from here, but keeping the
 * listener alive is also valid and lets the user submit another record. Doing
 * radio work mid-response is what makes a phone show "submit failed" for a
 * save that actually happened.
 *"}

{"content":"/****************************************************************************
 * app/velasight/vs_history.c
 *
 * One SD-NAND history engine serves two independent record kinds:
 *
 *   /mnt/sdnand/ai_agent/history/social/INDEX.JSN + R0000000.JSN
 *   /mnt/sdnand/ai_agent/history/chat/INDEX.JSN   + R0000000.JSN
 *
 * SOCIAL bodies use the cloud protocol's ttsMinutes/txtMinutes,
 * audioTimeline and emotionTimeline fields.  CHAT bodies are written by
 * vs_voice.c when a multi-turn idle-assistant conversation ends.  The two
 * kinds share all indexing, locking, atomic-write and bounded-retention
 * code, but have separate directories, sequence spaces and capacities.
 *
 * A record append is a small transaction: write the new body, atomically
 * replace the index with a candidate containing the new entry, update RAM,
 * then unlink the evicted oldest body.  Power loss can therefore leave an
 * unreferenced body, but never an index that points at a body deleted before
 * the new index became durable.  A failed index write is reported and the
 * previous state remains usable.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include <arch/board/board.h>
#include <netutils/cJSON.h>

#include "include/vs_history.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_VS_HISTORY_MAX_RECORDS
#  define CONFIG_VS_HISTORY_MAX_RECORDS 64
#endif

#define VS_HISTORY_ROOT       "/mnt/sdnand/ai_agent/history"
#define VS_HISTORY_INDEX_JSN  "INDEX.JSN"
#define VS_HISTORY_INDEX_TMP  "INDEX.TMP"
#define VS_HISTORY_PATH_MAX   96
#define VS_HISTORY_SEQ_MAX    9999999u
#define VS_HISTORY_KEY_FMT    "R%07u"
#define VS_HISTORY_BODY_FMT   "%s/R%07u.JSN"
#define VS_HISTORY_BODY_TMP   "%s/R%07u.TMP"
#define VS_HISTORY_INDEX_MAX  \
  ((size_t)CONFIG_VS_HISTORY_MAX_RECORDS * 1024u + 2u)
#define VS_HISTORY_SEQ_PROBES \
  ((unsigned int)CONFIG_VS_HISTORY_MAX_RECORDS + 1024u)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *const g_history_dir[VS_HISTORY_KIND_COUNT] =
{
  VS_HISTORY_ROOT "/social",
  VS_HISTORY_ROOT "/chat",
};

static struct vs_history_index_s *g_index[VS_HISTORY_KIND_COUNT];
static unsigned int g_count[VS_HISTORY_KIND_COUNT];
static unsigned int g_next_seq[VS_HISTORY_KIND_COUNT];
static bool g_kind_ready[VS_HISTORY_KIND_COUNT];
static bool g_opened;
static pthread_mutex_t g_history_lock = PTHREAD_MUTEX_INITIALIZER;

/* Fresh-store SOCIAL examples.  They are persisted through the same atomic
 * body/index path as future real sessions.  CHAT is intentionally never
 * seeded: fabricated user conversations must not appear as real history.
 */

static const struct vs_history_index_s g_social_seed[] =
{
  {
    VS_HISTORY_KIND_SOCIAL, "R0000000", "08/18 09:20", "上午交流",
    "整体较平稳\n后段略有疑惑", 55, 30, 15, false
  },
  {
    VS_HISTORY_KIND_SOCIAL, "R0000001", "08/17 16:40", "项目讨论",
    "对方需要进一步确认", 30, 20, 50, true
  },
  {
    VS_HISTORY_KIND_SOCIAL, "R0000002", "08/16 11:05", "日常记录",
    "交流进展顺利", 65, 25, 10, false
  },
};

/* These are the normalized contents of the protocol's response object.
 * schemaVersion/kind are local envelope metadata; protocol field names and
 * value types are preserved verbatim for preview/download and a future real
 * social-session producer.
 */

static const char *const g_social_seed_body[] =
{
  "{\"schemaVersion\":1,\"kind\":\"social\","
  "\"ttsMinutes\":\"\",\"txtMinutes\":"
