  pfd.fd = g_server.stoprd;
  pfd.events = POLLIN;
  pfd.revents = 0;
  do
    {
      ret = poll(&pfd, 1, timeout_ms);
    }
  while (ret < 0 && errno == EINTR);

  if (ret > 0 || vp_stopping())
    {
      return -ECANCELED;
    }

  return ret < 0 ? -errno : 0;
}

static int vp_write_all(int fd, const char *data, size_t len)
{
  size_t sent = 0;
  int waited = 0;

  while (sent < len)
    {
      int flags = MSG_DONTWAIT;
      ssize_t n;

#ifdef MSG_NOSIGNAL
      flags |= MSG_NOSIGNAL;
#endif
      n = send(fd, data + sent, len - sent, flags);

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          /* NuttX's buffered TCP send returns ENOMEM when the global socket
           * callback pool is momentarily busy, and EAGAIN/ENOBUFS when the
           * WRB or IOB pool is busy.  Phone browsers create short connection
           * bursts, so give completed closes a bounded chance to release
           * those resources.  The stop pipe makes this retry immediately
           * interruptible when the application leaves SoftAP.
           */

          if ((errno == ENOMEM || errno == EAGAIN || errno == ENOBUFS) &&
              waited < VP_RESPONSE_TIMEOUT_MS)
            {
              int ret = vp_wait_stop(VP_RESPONSE_RETRY_MS);

              if (ret < 0)
                {
                  return ret;
                }

              waited += VP_RESPONSE_RETRY_MS;
              continue;
            }

          return -errno;
        }

      if (n == 0)
        {
          return -EPIPE;
        }

      sent += (size_t)n;
    }

  return 0;
}

/****************************************************************************
 * Name: vp_read_request
 *
 * Description:
 *   Read until the headers plus the declared body have arrived, the cap is
 *   reached or the deadline passes.  Returns the total length, or negative on
 *   error.  A client that opens a connection and says nothing costs one
 *   timeout, not the service.
 *
 ****************************************************************************/

static int vp_read_request(int fd, struct vp_http_request_s *req)
{
  size_t total = 0;
  int waited = 0;

  for (; ; )
    {
      struct pollfd pfd[2];
      ssize_t n;
      int ret;

      ret = vp_http_parse(g_request, total, req);
      if (ret == 0)
        {
          if (req->action != VP_HTTP_ACTION_SAVE ||
              total >= req->header_len + req->content_length)
            {
              return (int)total;
            }
        }
      else if (ret != -EAGAIN)
        {
          return ret;
        }

      if (total >= sizeof(g_request) - 1)
        {
          return -E2BIG;
        }

      pfd[0].fd = fd;
      pfd[0].events = POLLIN;
      pfd[0].revents = 0;
      pfd[1].fd = g_server.stoprd;
      pfd[1].events = POLLIN;"}

