{"content":"bool vp_http_history_key_valid(const char *key)
{
  size_t i;

  if (key == NULL || strlen(key) != VELASIGHT_PROV_HISTORY_KEY_MAX ||
      key[0] != 'R')
    {
      return false;
    }

  for (i = 1; i < VELASIGHT_PROV_HISTORY_KEY_MAX; i++)
    {
      if (key[i] < '0' || key[i] > '9')
        {
          return false;
        }
    }

  return true;
}

int vp_http_parse(const char *buf, size_t len,
                  struct vp_http_request_s *req)
{
  const char *end;
  const char *line;
  const char *sp1;
  const char *sp2;
  size_t linelen;
  size_t targetlen;
  size_t remaining;
  size_t headers_len;
  bool is_post;
  bool have_length = false;
  bool form_type = false;
  size_t content_length = 0;

  if (buf == NULL || req == NULL)
    {
      return -EINVAL;
    }

  memset(req, 0, sizeof(*req));
  req->status = 400;

  /* No CRLFCRLF yet means either "keep reading" or "this client is not going
   * to stop", and the cap is what tells them apart.
   */

  end = NULL;
  if (len >= 4)
    {
      size_t i;

      for (i = 0; i + 4 <= len; i++)
        {
          if (memcmp(buf + i, "\r\n\r\n", 4) == 0)
            {
              end = buf + i;
              break;
            }
        }
    }

  if (end == NULL)
    {
      if (len >= VP_HTTP_MAX_HEADERS)
        {
          return vp_reject(req, 431);
        }

      return -EAGAIN;
    }

  headers_len = (size_t)(end - buf) + 4;
  if (headers_len > VP_HTTP_MAX_HEADERS)
    {
      return vp_reject(req, 431);
    }

  req->header_len = headers_len;

  /* Request line */

  line = buf;
  {
    const char *crlf = memchr(buf, '\r', (size_t)(end - buf) + 1);

    if (crlf == NULL)
      {
        return vp_reject(req, 400);
      }

    linelen = (size_t)(crlf - buf);
  }

  sp1 = memchr(line, ' ', linelen);
  if (sp1 == NULL)
    {
      return vp_reject(req, 400);
    }

  remaining = linelen - (size_t)(sp1 + 1 - line);
  sp2 = memchr(sp1 + 1, ' ', remaining);
  targetlen = sp2 != NULL ? (size_t)(sp2 - (sp1 + 1)) : remaining;
  if (targetlen == 0)
    {
      return vp_reject(req, 400);
    }

  if ((size_t)(sp1 - line) == 3 && memcmp(line, "GET", 3) == 0)
    {
      is_post = false;
    }
  else if ((size_t)(sp1 - line) == 4 && memcmp(line, "POST", 4) == 0)
    {
      is_post = true;
    }
  else
    {
      return vp_reject(req, 405);
    }

  /* The query string is not used; stripping it keeps "/" and "/?x=1" from
   * being two different paths.
   */

  {
    const char *target = sp1 + 1;
    const char *query = memchr(target, '?', targetlen);
    size_t pathlen = query != NULL ? (size_t)(query - target) : targetlen;

    if (!is_post)
      {
        bool root = pathlen == 1 && target[0] == '/';
        bool index = pathlen == 11 &&
                     memcmp(target, "/index.html", 11) == 0;

        if (root || index)
          {
            req->action = VP_HTTP_ACTION_PAGE;
            return 0;
          }

        if (pathlen == 8 && memcmp(target, "/history", 8) == 0)
          {
            req->action = VP_HTTP_ACTION_HISTORY_LIST;
            return 0;
          }

        if ((pathlen == 17 || pathlen == 26) &&
            memcmp(target, "/history/", 9) == 0)
          {
            memcpy(req->record_key, target + 9,
                   VELASIGHT_PROV_HISTORY_KEY_MAX);
            req->record_key[VELASIGHT_PROV_HISTORY_KEY_MAX] = '\0';
            if (!vp_http_history_key_valid(req->record_key))
              {
                return vp_reject(req, 404);
              }

            if (pathlen == 17)
              {
                req->action = VP_HTTP_ACTION_HISTORY_JSON;
                return 0;
              }

            if (memcmp(target + 17, "/download", 9) == 0)
              {
                req->action = VP_HTTP_ACTION_HISTORY_DOWNLOAD;
                return 0;
              }
          }

        return vp_reject(req, 404);
      }

    if (pathlen != 5 || memcmp(target, "/save", 5) != 0)
      {
        return vp_reject(req, 404);
      }
  }

  /* Headers.  Only three matter, and anything unexpected about them is a
   * refusal rather than a default, because this listener has no authentication
   * standing between it and the air.
   */

  {
    const char *cursor = buf + linelen + 2;

    while (cursor < end)
      {
        const char *crlf = memchr(cursor, '\r', (size_t)(end - cursor) + 1);
        const char *value;
        size_t valuelen;
        size_t thislen;

        if (crlf == NULL)
          {
            break;
          }

        thislen = (size_t)(crlf - cursor);
        if (thislen == 0)
          {
            break;
          }

        if (vp_header_value(cursor, thislen, "transfer-encoding",
                            &valuelen) != NULL)
          {
            return vp_reject(req, 400);
          }

        value = vp_header_value(cursor, thislen, "sec-fetch-site",
                                &valuelen);
        if (value != NULL)
          {
            while (valuelen > 0 &&
                   (value[valuelen - 1u] == ' ' ||
                    value[valuelen - 1u] == '\t'))
              {
                valuelen--;
              }

            /* Fetch Metadata is not authentication, but an explicit browser
             * cross-site navigation must never be allowed to mutate trusted-
             * LAN settings.  Missing headers remain accepted for captive
             * portals and older clients. */
            if (valuelen == sizeof("cross-site") - 1u &&
                vp_ci_prefix(value, valuelen, "cross-site"))
              {
                return vp_reject(req, 403);
              }
          }

        value = vp_header_value(cursor, thislen, "content-type", &valuelen);
        if (value != NULL)
          {
            form_type = valuelen >= strlen(g_form_type) &&
                        vp_ci_prefix(value, valuelen, g_form_type);
          }

        value = vp_header_value(cursor, thislen, "content-length", &valuelen);
        if (value != NULL)
          {
            size_t i;

            have_length = true;
            content_length = 0;
            if (valuelen == 0)
              {
                return vp_reject(req, 400);
              }

            for (i = 0; i < valuelen; i++)
              {
                if (value[i] < '0' || value[i] > '9')
                  {
                    return vp_reject(req, 400);
                  }

                if (content_length > (VP_HTTP_MAX_BODY + 1) / 10 + 1)
                  {
                    return vp_reject(req, 413);
                  }

                content_length = content_length * 10 +
                                 (size_t)(value[i] - '0');
              }
          }

        cursor = crlf + 2;
      }"}

{"content":"size_t vp_http_response_header(char *buf, size_t buflen, int status,
                               const char *content_type,
                               size_t content_length,
                               const char *disposition,
                               const char *record_key)
{
  int n;

  if (buf == NULL || buflen == 0 || content_type == NULL)
    {
      return 0;
    }

  if (disposition != NULL)
    {
      if ((strcmp(disposition, "inline") != 0 &&
           strcmp(disposition, "attachment") != 0) ||
          !vp_http_history_key_valid(record_key))
        {
          return 0;
        }

      n = snprintf(buf, buflen,
                   "HTTP/1.1 %d %s\r\n"
                   "Content-Type: %s\r\n"
                   "Content-Length: %zu\r\n"
                   "Content-Disposition: %s; filename=\"%s.json\"\r\n"
                   "Cache-Control: no-store\r\n"
                   "X-Content-Type-Options: nosniff\r\n"
                   "Connection: close\r\n\r\n",
                   status, vp_reason(status), content_type, content_length,
                   disposition, record_key);
    }
  else
    {
      n = snprintf(buf, buflen,
                   "HTTP/1.1 %d %s\r\n"
                   "Content-Type: %s\r\n"
                   "Content-Length: %zu\r\n"
                   "Cache-Control: no-store\r\n"
                   "X-Content-Type-Options: nosniff\r\n"
                   "Connection: close\r\n\r\n",
                   status, vp_reason(status), content_type, content_length);
    }

  return n < 0 || (size_t)n >= buflen ? 0 : (size_t)n;
}

size_t vp_http_history_head_fragment(char *buf, size_t buflen,
                                     unsigned int count)
{
  int n;

  if (buf == NULL || buflen == 0)
    {
      return 0;
    }

  n = snprintf(buf, buflen,
               VP_PAGE_HEAD
               "<h1>社交历史记录</h1>"
               "<p class=\"note\">按时间从新到旧，共 %u 条。</p>"
               "%s",
               count,
               count == 0 ? "<p>暂无可读取的社交历史记录。</p>" : "");
  return n < 0 || (size_t)n >= buflen ? 0 : (size_t)n;
}

size_t vp_http_history_entry_fragment(
    char *buf, size_t buflen,
    const struct velasight_prov_history_entry_s *entry)
{
  char key[(VELASIGHT_PROV_HISTORY_KEY_MAX * 6) + 1];
  char date[(VELASIGHT_PROV_HISTORY_DATE_MAX * 6) + 1];
  char title[(VELASIGHT_PROV_HISTORY_TITLE_MAX * 6) + 1];
  char summary[(VELASIGHT_PROV_HISTORY_SUMMARY_MAX * 6) + 1];
  int n;

  if (buf == NULL || buflen == 0 || entry == NULL ||
      memchr(entry->record_key, '\0', sizeof(entry->record_key)) == NULL ||
      memchr(entry->date, '\0', sizeof(entry->date)) == NULL ||
      memchr(entry->title, '\0', sizeof(entry->title)) == NULL ||
      memchr(entry->summary, '\0', sizeof(entry->summary)) == NULL ||
      !vp_http_history_key_valid(entry->record_key) ||
      entry->calm > 100 || entry->happy > 100 || entry->tense > 100)
    {
      return 0;
    }

  if (vp_html_escape(entry->record_key, key, sizeof(key)) < 0 ||
      vp_html_escape(entry->date, date, sizeof(date)) < 0 ||
      vp_html_escape(entry->title, title, sizeof(title)) < 0 ||
      vp_html_escape(entry->summary, summary, sizeof(summary)) < 0)
    {
      return 0;
    }

  n = snprintf(buf, buflen,
               "<article style=\"border-top:1px solid #ddd;padding:14px 0\">"
               "<h2 style=\"font-size:1.05rem;margin:0 0 4px\">%s</h2>"
               "<p class=\"note\">%s · %s%s</p>"
               "<p style=\"white-space:pre-wrap\">%s</p>"
               "<p class=\"note\">平静 %u%% · 开心 %u%% · 紧张 %u%%</p>"
               "<p><a href=\"/history/%s\">预览 JSON</a> · "
               "<a href=\"/history/%s/download\">下载</a></p>"
               "</article>",
               title, date, key, entry->incomplete ? " · 未完整" : "",
               summary, (unsigned int)entry->calm,
               (unsigned int)entry->happy, (unsigned int)entry->tense,
               entry->record_key, entry->record_key);
  return n < 0 || (size_t)n >= buflen ? 0 : (size_t)n;
}

size_t vp_http_history_tail_fragment(char *buf, size_t buflen)
{
  int n;

  if (buf == NULL || buflen == 0)
    {
      return 0;
    }

  n = snprintf(buf, buflen,
               "<p class=\"note\"><a href=\"/\">返回配网页面</a></p>"
               VP_PAGE_TAIL);
  return n < 0 || (size_t)n >= buflen ? 0 : (size_t)n;
}
"}

{"content":"static bool vp_history_enabled(void)
{
  return g_server.history.snapshot != NULL && g_server.history.open != NULL;
}

static int vp_send_status(int fd, int status, const char *message)
{
  size_t len = vp_http_status_page(g_response, sizeof(g_response), status,
                                   message);

  return len == 0 ? -EOVERFLOW : vp_write_response(fd, g_response, len);
}

static int vp_history_error_status(int error)
{
  if (error == -ENOENT)
    {
      return 404;
    }

  if (error == -ENODEV || error == -EAGAIN)
    {
      return 503;
    }

  return 500;
}

static int vp_history_snapshot(
    struct velasight_prov_history_entry_s **entries_out,
    unsigned int *count_out)
{
  struct velasight_prov_history_entry_s *entries = NULL;
  unsigned int total = 0;
  unsigned int copied = 0;
  unsigned int attempt;
  int ret;

  if (entries_out == NULL || count_out == NULL || !vp_history_enabled())
    {
      return -ENODEV;
    }

  *entries_out = NULL;
  *count_out = 0;
  ret = g_server.history.snapshot(0, NULL, 0, &total, &copied,
                                  g_server.history.arg);
  if (ret < 0)
    {
      return ret;
    }

  for (attempt = 0; attempt < 2; attempt++)
    {
      unsigned int current_total = 0;

      if (total > VELASIGHT_PROV_HISTORY_MAX_ENTRIES)
        {
          return -E2BIG;
        }

      if (total == 0)
        {
          return 0;
        }

      entries = calloc(total, sizeof(*entries));
      if (entries == NULL)
        {
          return -ENOMEM;
        }

      copied = 0;
      ret = g_server.history.snapshot(0, entries, total, &current_total,
                                      &copied, g_server.history.arg);
      if (ret < 0)
        {
          free(entries);
          return ret;
        }

      if (copied > total)
        {
          free(entries);
          return -EBADMSG;
        }

      if (current_total <= total)
        {
          *entries_out = entries;
          *count_out = copied;
          return 0;
        }

      free(entries);
      entries = NULL;
      total = current_total;
    }

  return -EAGAIN;
}

static int vp_send_history_list(int fd)
{
  struct velasight_prov_history_entry_s *entries = NULL;
  unsigned int count = 0;
  unsigned int i;
  size_t body_length = 0;
  size_t len;
  uint64_t deadline_ms;
  int status;
  int ret;

  if (!vp_history_enabled())
    {
      return vp_send_status(fd, 404, "历史记录功能未启用。");
    }

  ret = vp_history_snapshot(&entries, &count);
  if (ret < 0)
    {
      status = vp_history_error_status(ret);
      return vp_send_status(fd, status,
                            status == 503 ? "历史存储暂不可用。" :
                            status == 404 ? "历史记录不存在。" :
                                            "读取历史记录失败。");
    }

  len = vp_http_history_head_fragment(g_response, sizeof(g_response), count);
  if (len == 0)
    {
      free(entries);
      return vp_send_status(fd, 500, "生成历史页面失败。");
    }
  body_length = len;

  for (i = 0; i < count; i++)
    {
      len = vp_http_history_entry_fragment(g_response, sizeof(g_response),
                                           &entries[i]);
      if (len == 0 || body_length > SIZE_MAX - len)
        {
          free(entries);
          return vp_send_status(fd, 500, "历史索引格式无效。");
        }

      body_length += len;
    }

  len = vp_http_history_tail_fragment(g_response, sizeof(g_response));
  if (len == 0 || body_length > SIZE_MAX - len)
    {
      free(entries);
      return vp_send_status(fd, 500, "生成历史页面失败。");
    }
  body_length += len;

  len = vp_http_response_header(g_response, sizeof(g_response), 200,
                                "text/html; charset=utf-8", body_length,
                                NULL, NULL);
  if (len == 0)
    {
      free(entries);
      return -EOVERFLOW;
    }

  ret = vp_response_deadline(&deadline_ms);
  if (ret == 0)
    {
      ret = vp_write_all(fd, g_response, len, deadline_ms);
    }
  if (ret == 0)
    {
      len = vp_http_history_head_fragment(g_response, sizeof(g_response),
                                          count);
      ret = len == 0 ? -EOVERFLOW :
                       vp_write_all(fd, g_response, len, deadline_ms);
    }

  for (i = 0; ret == 0 && i < count; i++)
    {
      len = vp_http_history_entry_fragment(g_response, sizeof(g_response),
                                           &entries[i]);
      ret = len == 0 ? -EBADMSG :
                       vp_write_all(fd, g_response, len, deadline_ms);
    }

  if (ret == 0)
    {
      len = vp_http_history_tail_fragment(g_response, sizeof(g_response));
      ret = len == 0 ? -EOVERFLOW :
                       vp_write_all(fd, g_response, len, deadline_ms);
    }

  free(entries);
  return ret;
}

static int vp_send_history_file(int fd, const char *record_key,
                                bool download)
{
  size_t remaining;
  size_t size = 0;
  size_t len;
  uint64_t deadline_ms;
  int history_fd = -1;
  int status;
  int ret;

  if (!vp_history_enabled())
    {
      return vp_send_status(fd, 404, "历史记录功能未启用。");
    }

  ret = g_server.history.open(record_key, &history_fd, &size,
                              g_server.history.arg);
  if (ret < 0 || history_fd < 0)
    {
      if (history_fd >= 0)
        {
          close(history_fd);
        }

      if (ret >= 0)
        {
          ret = -EBADMSG;
        }
      status = vp_history_error_status(ret);
      return vp_send_status(fd, status,
                            status == 503 ? "历史存储暂不可用。" :
                            status == 404 ? "历史记录不存在。" :
                                            "打开历史记录失败。");
    }

  len = vp_http_response_header(
      g_response, sizeof(g_response), 200,
      download ? "application/json" : "application/json; charset=utf-8",
      size, download ? "attachment" : NULL,
      download ? record_key : NULL);
  if (len == 0)
    {
      close(history_fd);
      return -EOVERFLOW;
    }

  ret = vp_response_deadline(&deadline_ms);
  if (ret == 0)
    {
      ret = vp_write_all(fd, g_response, len, deadline_ms);
    }
  remaining = size;
  while (ret == 0 && remaining > 0)
    {
      size_t wanted = remaining < sizeof(g_response) ? remaining :
                                                       sizeof(g_response);
      ssize_t n = read(history_fd, g_response, wanted);

      if (n < 0 && errno == EINTR)
        {
          continue;
        }

      if (n <= 0)
        {
          ret = n < 0 ? -errno : -EIO;
          break;
        }

      ret = vp_write_all(fd, g_response, (size_t)n, deadline_ms);
      remaining -= (size_t)n;
    }

  close(history_fd);
  return ret;
}

/****************************************************************************
 * Name: vp_handle
 *
 * Description:
 *   Serve one connection.  Sets *saved when credentials were persisted and
 *   *save_status to 0 or the negative errno of a failed save, so the caller can
 *   notify the application only after the socket is gone.
 *
 ****************************************************************************/

static void vp_handle(int fd, bool *saved, int *save_status,
                      uint32_t *generation)
{
  struct velasight_prov_credentials_s cred;
  struct vp_http_request_s req;
  size_t len = 0;
  int ret;

  *saved = false;
  *save_status = 0;

  ret = vp_read_request(fd, &req);
  if (ret < 0)
    {
      if (ret == -E2BIG)
        {
          len = vp_http_status_page(g_response, sizeof(g_response), 431,
                                    "请求过大。");
        }
      else
        {
          /* Nothing usable arrived; answering a client that already gave up
           * is not worth a second syscall.
           */

          return;
        }
    }
  else if (req.action == VP_HTTP_ACTION_PAGE)
    {
       {
         struct velasight_prov_credentials_s current;
         const char *ssid = NULL;

         if (velasight_provisioning_load(&current) == 0)
           ssid = current.ssid;
         len = vp_http_form_page_with_ssid_history(
             g_response, sizeof(g_response), NULL, ssid,
             vp_history_enabled());
       }
    }
  else if (req.action == VP_HTTP_ACTION_HISTORY_LIST)
    {
      ret = vp_send_history_list(fd);
      if (ret < 0)
        {
          printf("provision_web: history list write failed: %d\n", ret);
        }
      return;
    }
  else if (req.action == VP_HTTP_ACTION_HISTORY_JSON ||
           req.action == VP_HTTP_ACTION_HISTORY_DOWNLOAD)
    {
      ret = vp_send_history_file(
          fd, req.record_key,
          req.action == VP_HTTP_ACTION_HISTORY_DOWNLOAD);
      if (ret < 0)
        {
          printf("provision_web: history file write failed: %d\n", ret);
        }
      return;
    }
  else if (req.action == VP_HTTP_ACTION_REJECT)
    {
      len = vp_http_status_page(g_response, sizeof(g_response), req.status,
                               req.status == 404 ? "页面不存在。" :
                               req.status == 403 ? "不允许跨站提交。" :
                               req.status == 405 ? "不支持该请求方法。" :
                               req.status == 413 ? "提交内容过大。" :
                               req.status == 415 ? "提交格式不受支持。" :
                               req.status == 411 ? "缺少 Content-Length。" :
                                                   "请求无法解析。");
    }
  else
    {
      memset(&cred, 0, sizeof(cred));
      ret = vp_form_parse(g_request + req.header_len, req.content_length,
                          &cred);
      if (ret < 0)
        {
          /* No detail about which field failed and no echo of what was typed:
           * the notice has to be useful to the person at the phone without
           * repeating a passphrase back over an open network.
           */

           {
             struct velasight_prov_credentials_s current;
             const char *ssid = NULL;

             if (velasight_provisioning_load(&current) == 0)
               ssid = current.ssid;
             len = vp_http_form_page_with_ssid(
                 g_response, sizeof(g_response),
                 "SSID 需 1-32 字节，密码需留空或 8-63 字节，"
                 "API key 需为可打印字符，请检查后重试。", ssid);
           }
          if (len > 0)
            {
              /* Reuse the form page body but answer 400, so a client that
               * checks the status still learns the submit failed.
               */

              len = vp_http_status_page(g_response, sizeof(g_response), 400,
                                        "SSID 需 1-32 字节，密码需留空或 "
                                        "8-63 字节。");
            }
        }
        else
          {
            struct velasight_prov_credentials_s previous;
            bool have_previous = velasight_provisioning_load(&previous) == 0;

            /* None of the three secret fields are pre-filled in HTML.  An
             * ordinary Wi-Fi-only resubmit must not erase any of them. */
            if (cred.api_key[0] == '\0' && have_previous)
              {
                snprintf(cred.api_key, sizeof(cred.api_key), "%s",
                         previous.api_key);
              }

            if (cred.volc_appid[0] == '\0' && have_previous)
              {
                snprintf(cred.volc_appid, sizeof(cred.volc_appid), "%s",
                         previous.volc_appid);
              }

            if (cred.volc_token[0] == '\0' && have_previous)
              {
                snprintf(cred.volc_token, sizeof(cred.volc_token), "%s",
                         previous.volc_token);
              }

            cred.generation = vp_store_next_generation(g_server.store_path);
          ret = vp_store_save(g_server.store_path, &cred);
          if (ret < 0)
            {
              *saved = false;
              *save_status = ret;
              len = vp_http_status_page(g_response, sizeof(g_response), 500,
                                        "写入持久存储失败，凭据未保存。");
            }
          else
            {
              *saved = true;
              *save_status = 0;
              *generation = cred.generation;
              len = vp_http_saved_page(g_response, sizeof(g_response),
                                       cred.ssid, cred.generation,
                                       cred.open_network);
            }
        }
    }

  if (len > 0)
    {
      ret = vp_write_response(fd, g_response, len);
      if (ret < 0)
        {
          /* Transport failure does not undo a completed persistent save.
           * In particular, NuttX may return ENOMEM when TCP write buffers are
           * temporarily exhausted by repeated phone connections.  Report the
           * stored result to the application; only vp_store_save() decides
           * whether the credentials were saved.
           */

          printf("provision_web: response write failed: %d\n", ret);
        }
    }
}

static void *vp_thread(void *arg)
{
  (void)arg;

  for (; ; )
    {
      struct pollfd pfd[2];
      uint32_t generation = 0;
      int save_status = 0;
      bool saved = false;
      bool stopping;
      int fd;
      int ret;

      pthread_mutex_lock(&g_lock);
      stopping = g_server.stopping;
      pthread_mutex_unlock(&g_lock);
      if (stopping)
        {
          break;
        }

      pfd[0].fd = g_server.listenfd;
      pfd[0].events = POLLIN;
      pfd[0].revents = 0;
      pfd[1].fd = g_server.stoprd;
      pfd[1].events = POLLIN;
      pfd[1].revents = 0;

      /* Polling rather than blocking in accept(): stop() then needs no signal
       * and no socket shutdown trick that may or may not wake accept on a
       * given stack.
       *
       * This requires CONFIG_NET_TCPBACKLOG on NuttX, which the Kconfig
       * depends on.  Without it TCP_BACKLOG events never fire, POLLIN on a
       * listening socket is unreachable, and accept() blocks with no timeout
       * at all -- measured on the board as a service that reported
       * "listening" and then answered nothing.
       */

      ret = poll(pfd, 2, VP_ACCEPT_POLL_MS);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }"}

{"content":"int velasight_provisioning_start(
    const struct velasight_prov_config_s *config)
{
  struct velasight_prov_config_s cfg;
  struct sockaddr_in addr;
  pthread_attr_t attr;
  uint16_t port;
  int stopfds[2];
  int one = 1;
  int fd;
  int ret;

  memset(&cfg, 0, sizeof(cfg));
  if (config != NULL)
    {
      cfg = *config;
    }

  if (cfg.store_path != NULL &&
      strlen(cfg.store_path) >= VP_STORE_PATH_MAX)
    {
      return -ENAMETOOLONG;
    }

  if ((cfg.history.snapshot == NULL) != (cfg.history.open == NULL))
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_lock);
  vp_reap_locked();
  if (g_server.state != VP_STATE_IDLE)
    {
      pthread_mutex_unlock(&g_lock);
      return -EALREADY;
    }

  if (pipe(stopfds) < 0)
    {
      ret = -errno;
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  port = cfg.port != 0 ? cfg.port :
         (uint16_t)CONFIG_VELASIGHT_PROVISION_PORT;

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      ret = -errno;
      close(stopfds[0]);
      close(stopfds[1]);
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));

  memset(&addr, 0, sizeof(addr));
  addr.sin_family      = AF_INET;
  addr.sin_port        = htons(port);
  addr.sin_addr.s_addr = htonl(INADDR_ANY);

  if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0 ||
      listen(fd, 2) < 0)
    {
      ret = -errno;
      close(fd);
      close(stopfds[0]);
      close(stopfds[1]);
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  g_server.listenfd   = fd;
  g_server.stopping   = false;
  g_server.one_shot   = cfg.one_shot;
  g_server.generation = 0;
  g_server.on_saved   = cfg.on_saved;
  g_server.cb_arg     = cfg.cb_arg;
  g_server.history   = cfg.history;
  g_server.stoprd     = stopfds[0];
  g_server.stopwr     = stopfds[1];
  g_server.clientfd   = -1;
  snprintf(g_server.store_path, sizeof(g_server.store_path), "%s",
           cfg.store_path != NULL ? cfg.store_path :
           CONFIG_VELASIGHT_PROVISION_STORE);
  g_server.state = VP_STATE_RUNNING;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, VP_THREAD_STACK);
  ret = pthread_create(&g_server.thread, &attr, vp_thread, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      close(fd);
      close(stopfds[0]);
      close(stopfds[1]);
      g_server.listenfd = -1;
      g_server.clientfd = -1;
      g_server.stoprd = -1;
      g_server.stopwr = -1;
      g_server.state = VP_STATE_IDLE;
      pthread_mutex_unlock(&g_lock);
      return -ret;
    }

  pthread_mutex_unlock(&g_lock);

  printf("provision_web: listening on 0.0.0.0:%u, store %s\n",
         (unsigned)port, g_server.store_path);
  return 0;
}

int velasight_provisioning_stop(void)
{
  pthread_t thread;

  pthread_mutex_lock(&g_lock);
  vp_reap_locked();
  if (g_server.state != VP_STATE_RUNNING)
    {
      pthread_mutex_unlock(&g_lock);
      return -EALREADY;
    }

  g_server.stopping = true;
  thread = g_server.thread;

  /* The stop pipe interrupts request parsing and response retries.  If the
   * request was already in close(), turn that close into an abortive close so
   * SO_LINGER cannot make the network-switch worker wait for a phone ACK. */

  if (g_server.clientfd >= 0)
    {
      struct linger linger;

      linger.l_onoff = 1;
      linger.l_linger = 0;
      (void)setsockopt(g_server.clientfd, SOL_SOCKET, SO_LINGER,
                       &linger, sizeof(linger));
    }

  if (g_server.stopwr >= 0)
    {
      char wake = 1;

      while (write(g_server.stopwr, &wake, sizeof(wake)) < 0 &&
             errno == EINTR)
        {
        }
    }

  /* Called from the saved callback, which runs on the listener thread: joining
   * ourselves would deadlock, so only ask the loop to end and let the normal
   * exit path close the socket.  A later stop() from the application reaps it.
   */

  if (pthread_equal(thread, pthread_self()))
    {
      pthread_mutex_unlock(&g_lock);
      return 0;
    }

  pthread_mutex_unlock(&g_lock);
  pthread_join(thread, NULL);

  pthread_mutex_lock(&g_lock);
  if (g_server.stopwr >= 0)
    {
      close(g_server.stopwr);
      g_server.stopwr = -1;
    }

  g_server.state = VP_STATE_IDLE;
  pthread_mutex_unlock(&g_lock);
  return 0;
}

bool velasight_provisioning_is_running(void)
{
  bool running;

  pthread_mutex_lock(&g_lock);
  running = g_server.state == VP_STATE_RUNNING;
  pthread_mutex_unlock(&g_lock);
  return running;
}

uint32_t velasight_provisioning_generation(void)
{
  uint32_t generation;

  pthread_mutex_lock(&g_lock);
  generation = g_server.generation;
  pthread_mutex_unlock(&g_lock);
  return generation;
}

int velasight_provisioning_load_from(
    const char *path, struct velasight_prov_credentials_s *out)
{
  if (path == NULL || out == NULL)
    {
      return -EINVAL;
    }

  return vp_store_load(path, out);
}

int velasight_provisioning_load(
    struct velasight_prov_credentials_s *out)
{
  char path[VP_STORE_PATH_MAX];

  pthread_mutex_lock(&g_lock);
  if (g_server.store_path[0] != '\0')
    {
      snprintf(path, sizeof(path), "%s", g_server.store_path);
    }
  else
    {
      snprintf(path, sizeof(path), "%s", CONFIG_VELASIGHT_PROVISION_STORE);
    }

  pthread_mutex_unlock(&g_lock);

  return velasight_provisioning_load_from(path, out);
}
