/* Read out whatever the capture driver is still holding and forward it to
 * the ASR stream, then abort the device.  Used only on manual stop: the
 * user's last word can still be sitting in the driver's buffers (up to
 * CONFIG_AUDIO_NUM_BUFFERS x CONFIG_AUDIO_BUFFER_NUMBYTES, about 256 ms at
 * 16 kHz) when the button is released, and discarding it there made short
 * utterances come back as "no valid speech".  Bounded by a short wall-clock
 * budget rather than a fixed read count, so it cannot hang a conversation if
 * the driver stops producing buffers. */

#define VS_VOICE_DRAIN_BUDGET_MS 100

static void vs_voice_drain_capture(struct vs_audio_cap_s *cap,
                                   voice_asr_stream_t *stream)
{
  unsigned char chunk[AGENT_ASR_CHUNK_SIZE];
  uint32_t deadline = vs_voice_now_ms() + VS_VOICE_DRAIN_BUDGET_MS;

  while ((int32_t)(vs_voice_now_ms() - deadline) < 0)
    {
      int n = vs_audio_capture_read(cap, chunk, sizeof(chunk));

      if (n == -EAGAIN || n == -EWOULDBLOCK)
        {
          /* Nothing buffered right now.  A short sleep keeps this from
           * busy-polling the mutex, but no more of the budget is spent
           * waiting for audio that may simply not arrive. */

          usleep(5000);
          continue;
        }

      if (n <= 0)
        {
          break;
        }

      (void)voice_asr_stream_send(stream, chunk, (size_t)n);
    }

  vs_audio_capture_abort(cap);
}

