"""Turn off MiMo's deep-thinking mode on the voice paths.

mimo-v2.5 enables it by default: the model emits a reasoning_content chain of
thought before the answer, and max_completion_tokens caps thinking and answer
together.  None of this code reads reasoning_content -- extract_text() takes
"content" -- so every reasoning token is latency spent on output that is thrown
away.  Measured on hardware, a 319-byte answer took 95 s to generate.

Parameter and defaults per the provider's own documentation:
https://mimo.mi.com/docs/zh-CN/quick-start/usage-guide/text-generation/deep-thinking
"""

import sys

AI = "/home/mi/vela_competition/contest/packages/ai_agent/"


def edit(path, pairs):
    full = AI + path
    src = open(full, encoding="utf-8").read()
    for label, old, new in pairs:
        if src.count(old) != 1:
            sys.exit("%s / %s: %d matches, expected 1"
                     % (path, label, src.count(old)))
        src = src.replace(old, new)
    open(full, "w", encoding="utf-8").write(src)
    print("patched", path)


# is_openai_compat_host() also covers openai.com and openrouter.ai, which do not
# know this field, so the test has to be narrower than that.
HELPER = """/* MiMo's deep-thinking switch.  Narrower than is_openai_compat_host() on
 * purpose: "thinking" is not an OpenAI-standard field, and the other
 * OpenAI-compatible providers behind that helper have no reason to see it.
 *
 * mimo-v2.5 and mimo-v2.5-pro think by default, emitting a reasoning_content
 * chain of thought ahead of the answer.  Nothing here reads that field, and
 * max_completion_tokens bounds thinking and answer together, so leaving it on
 * spends response time producing output that is discarded and squeezes the room
 * left for the reply.  See the provider's deep-thinking documentation.
 */
static bool llm_host_wants_thinking_off(const char* host)
{
    return strstr(host, "xiaomimimo.com") != NULL;
}

"""

