# With thinking off, the whole budget is the answer, so the ceiling can come
# down to what a spoken reply actually needs.  Kept well above the prompt's
# 150-character cap so a request that somehow keeps thinking still completes.
edit("include/agent_config.h", [
    ("openai token ceiling",
     """#define AGENT_LLM_MAX_TOKENS_OPENAI 16384""",
     """/* Applies to the OpenAI-compatible hosts, which is the path MiMo uses.
