static uint32_t vs_display_now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

static lv_color_t vs_rgb(uint8_t red, uint8_t green, uint8_t blue)
{
