"""Shorten the level ring's arc instead of shrinking it, prebuffer TTS audio so
playback cannot starve, persist the volume, and record what the TTS server
actually sends so the five-second idle wait can be removed properly."""

import sys

AI = "/home/mi/vela_competition/contest/packages/ai_agent/"
