#!/usr/bin/env python3
"""Put the write on the far side of a rendered frame.

vs_handle_event() only mutates runtime; the frame it produces is painted by
vs_display_tick() at the bottom of the main loop.  So a blocking write called
from the handler happens before anything reaches the panel, and the freeze lands
on the page the user is leaving.  Deferring the write by one loop pass lets the
"saving" frame be painted first.
"""

import sys

WS = ("/home/mi/vela_competition/contest/"
      "contest2026_264_VelaSightsuixingAIzhinengyanjing/")


def edit(path, pairs):
    full = WS + path
    src = open(full, encoding="utf-8").read()
    for label, old, new in pairs:
        if src.count(old) != 1:
            sys.exit("%s / %s: %d matches, expected 1"
                     % (path, label, src.count(old)))
        src = src.replace(old, new)
    open(full, "w", encoding="utf-8").write(src)
    print("patched", path)


