#!/usr/bin/env python3
"""Make TTS play completely and start early.

Protocol facts established against the vendor's own reference client
(https://developer.volcengine.com/articles/7500048059624554515) and the
message-type-specific-flags table it prints:

    flags 0  audio ACK, no sequence number
    flags 1  sequence number > 0
    flags 2  last message from server (seq < 0)
    flags 3  sequence number < 0

    audio payload = seq(4, signed BE) + payload_size(4, BE) + data

So the parser here was right: end of stream is sequence_number < 0, and the
byte layout matches.  The truncation seen on hardware was therefore not a
parsing error -- the idle timeout was firing before that frame could arrive.
Evidence: every session reported "0 frontend", meaning the epilogue the service
sends after the audio never got a chance to appear either.
"""

import sys

AI = "/home/mi/vela_competition/contest/packages/ai_agent/"
WS = ("/home/mi/vela_competition/contest/"
      "contest2026_264_VelaSightsuixingAIzhinengyanjing/")


def edit(full, pairs):
    src = open(full, encoding="utf-8").read()
    for label, old, new in pairs:
        if src.count(old) != 1:
            sys.exit("%s / %s: %d matches, expected 1"
                     % (full.rsplit("/", 1)[-1], label, src.count(old)))
        src = src.replace(old, new)
    open(full, "w", encoding="utf-8").write(src)
    print("patched", full.rsplit("/", 1)[-1])


