#!/usr/bin/env python3
"""Rebuffering instead of gaps, and a watermark that learns.

The arrival rate measured on hardware swings between 0.60x and 1.93x real
time, so no fixed pre-buffer can be right: 1 s starves on the slow sessions
and 3 s was larger than a whole reply.  Two changes:

  - when the pipeline empties mid-reply, mute and disable the DAC's transmit
    interrupt (AUDIOIOC_PAUSE) instead of letting it run on an empty FIFO, and
    resume once audio has built back up.  The driver's enqueuebuffer() skips
    re-arming while paused, so buffers can keep queueing during the gap;

  - carry the watermark across replies and raise it whenever a reply starves,
    lowering it slowly when one plays clean.  Arrival rate is a property of
    the service and the link, not of one sentence, so it is worth remembering.
"""

import sys

WS = ("/home/mi/vela_competition/contest/"
      "contest2026_264_VelaSightsuixingAIzhinengyanjing/")


def edit(path, pairs):
    full = WS + path
    src = open(full, encoding="utf-8").read()
    for label, old, new in pairs:
        if src.count(old) != 1:
            sys.exit("%s / %s: %d matches, expected 1"
                     % (path, label, src.count(old)))
        src = src.replace(old, new)
    open(full, "w", encoding="utf-8").write(src)
    print("patched", path)


