#!/usr/bin/env python3
"""Relieve the two local bottlenecks behind the playback gaps.

1. Network buffer pool.  32 IOBs of 1514 bytes is 48 KB for the whole system,
   and IOB_THROTTLE=8 reserves eight of those away from TCP read-ahead, so the
   receive side has about 24.  A single 16 KB TLS record -- the maximum
   MBEDTLS_SSL_IN_CONTENT_LEN allows, and mbedtls cannot decrypt a record until
   all of it has arrived -- occupies eleven.  Two in flight is twenty-two, which
   is already the ceiling, so the window closes, reopens when we drain, and the
   audio arrives in the bursts the logs show.

   The pool cannot move to PSRAM: bk7258_psram.c states that PSRAM is not
   powered until the CP answers a mailbox request, which happens after
   nx_start() has already run iob_initialize().  So the pool grows inside SRAM,
   by as much as SRAM can spare.

2. Flat thread priorities.  Every velasight thread runs at
   SCHED_PRIORITY_DEFAULT (100) because only the stack size was ever set; the
   voice worker that drains the TTS socket therefore competes on equal terms
   with the UI loop, and with CONFIG_RR_INTERVAL=200 it waits behind any frame
   the UI decides to push.  Whatever it spends waiting, the IOBs it is holding
   spend waiting too, which feeds straight back into (1).
"""

import sys

WS = ("/home/mi/vela_competition/contest/"
      "contest2026_264_VelaSightsuixingAIzhinengyanjing/")
OV = "/home/mi/vela_competition/contest/"


def edit(full, pairs):
    src = open(full, encoding="utf-8").read()
    for label, old, new in pairs:
        if src.count(old) != 1:
            sys.exit("%s / %s: %d matches, expected 1"
                     % (full.rsplit("/", 1)[-1], label, src.count(old)))
        src = src.replace(old, new)
    open(full, "w", encoding="utf-8").write(src)
    print("patched", full.rsplit("/", 1)[-1])


# ============================================ 1. IOB pool (defconfig)
#
# defconfig is savedefconfig format, so only non-default values appear.  Both
# of these differ from the Kconfig default, so both must be written.

path = OV + "vendor/beken/boards/bk7258/bk7258-ap/configs/ai_agent/defconfig"
src = open(path, encoding="utf-8").read()

if "CONFIG_IOB_NBUFFERS=" in src:
    import re
    before = src
    src = re.sub(r"^CONFIG_IOB_NBUFFERS=\d+$", "CONFIG_IOB_NBUFFERS=40",
                 src, count=1, flags=re.M)
    if src == before:
        sys.exit("IOB_NBUFFERS present but not replaced")
else:
    sys.exit("IOB_NBUFFERS not in defconfig; would need a new line in sorted "
             "position -- inspect manually")

if "CONFIG_IOB_THROTTLE=" in src:
    import re
    before = src
    src = re.sub(r"^CONFIG_IOB_THROTTLE=\d+$", "CONFIG_IOB_THROTTLE=4",
                 src, count=1, flags=re.M)
    if src == before:
        sys.exit("IOB_THROTTLE present but not replaced")
else:
    sys.exit("IOB_THROTTLE not in defconfig -- inspect manually")

open(path, "w", encoding="utf-8").write(src)
print("patched defconfig (IOB 32->40, throttle 8->4)")


# ============================================ 2. thread priorities
#
# Kept well under CONFIG_SCHED_HPWORKPRIORITY (224) so the network stack still
# preempts everything here, which is the order that matters.

edit(WS + "app/velasight/include/vs_app.h", [
    ("priority constants",
     """#ifndef __APP_VELASIGHT_INCLUDE_VS_APP_H
#define __APP_VELASIGHT_INCLUDE_VS_APP_H""",
     """#ifndef __APP_VELASIGHT_INCLUDE_VS_APP_H
#define __APP_VELASIGHT_INCLUDE_VS_APP_H

/* Thread priorities, relative to SCHED_PRIORITY_DEFAULT (100).
 *
 * They were all left at the default, which put the UI loop, the voice worker
 * and the audio threads at the same level.  With CONFIG_RR_INTERVAL=200 that
 * means a thread which does not yield promptly can hold the others off, and
 * the two that must not be held off are the ones moving audio: the capture and
 * playback threads keep the driver's 256 ms queue serviced, and the voice
 * worker drains the TTS socket -- while it waits, the IOBs holding that data
 * are not returned to the pool and the sender's window stays shut.
 *
 * The UI is the one that can afford to wait, so it stays at the bottom.
 * Everything here is far below CONFIG_SCHED_HPWORKPRIORITY (224), so the
 * network stack still preempts all of it.
 */

/* Moves samples between the driver and the staging rings.  Highest of the
 * four: it runs briefly and often, and being late shows up as a gap the
 * listener hears.
 */

#define VS_PRIORITY_AUDIO  (SCHED_PRIORITY_DEFAULT + 10)

/* Runs the cloud round trip, including the socket reads that free IOBs. */

#define VS_PRIORITY_VOICE  (SCHED_PRIORITY_DEFAULT + 5)

/* Key sampling.  Above the UI so a press is timestamped promptly, below the
 * audio path because 5 ms of jitter in a debounce window is invisible.
 */

#define VS_PRIORITY_INPUT  (SCHED_PRIORITY_DEFAULT + 1)"""),
])

edit(WS + "app/velasight/vs_app.c", [
    ("input priority",
     """  ret = task_create("velasight_input", SCHED_PRIORITY_DEFAULT + 1, 2048,
                    vs_input_worker, NULL);""",
     """  ret = task_create("velasight_input", VS_PRIORITY_INPUT, 2048,
                    vs_input_worker, NULL);"""),
])

# The voice worker: created in vs_voice.c, needs an explicit schedparam because
# pthread_create otherwise inherits the creator's priority.
edit(WS + "app/velasight/vs_voice.c", [
    ("voice worker priority",
     """  ret = pthread_attr_setstacksize(&attr, CONFIG_VS_VOICE_STACKSIZE);""",
     """  ret = pthread_attr_setstacksize(&attr, CONFIG_VS_VOICE_STACKSIZE);
  if (ret == 0)
    {
      struct sched_param param;

      /* Explicit, because pthread_create() would otherwise inherit the UI
       * thread's priority and this worker would then have to take turns with
       * frame pushes while a TTS socket waits to be drained.
       */

      param.sched_priority = VS_PRIORITY_VOICE;
      ret = pthread_attr_setschedparam(&attr, &param);
      if (ret == 0)
        {
          ret = pthread_attr_setschedpolicy(&attr, SCHED_FIFO);
        }
    }
"""),
])

# Both audio threads.
edit(WS + "app/velasight/vs_audio.c", [
    ("capture thread priority",
     """  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  ret = pthread_create(&cap->thread, &attr, vs_audio_cap_thread, cap);""",
     """  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  vs_audio_thread_priority(&attr);
  ret = pthread_create(&cap->thread, &attr, vs_audio_cap_thread, cap);"""),

    ("playback thread priority",
     """  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  ret = pthread_create(&pb->thread, &attr, vs_audio_pb_thread, pb);""",
     """  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  vs_audio_thread_priority(&attr);
  ret = pthread_create(&pb->thread, &attr, vs_audio_pb_thread, pb);"""),

    ("priority helper",
     """static uint64_t vs_audio_now_ms(void)""",
     """/* Raise a buffer-moving thread above the UI.
 *
 * Both of these run briefly and often -- one driver buffer is 64 ms of audio,
 * and the queue is four of them -- so what they need is to be scheduled
 * promptly rather than for long.  Inheriting the creator's priority put them
 * behind frame pushes, which is how a 256 ms queue runs dry.
 *
 * Failure is not fatal: the thread still works at the inherited priority, it
 * is just easier to starve, so this reports and continues.
 */

static void vs_audio_thread_priority(pthread_attr_t *attr)
{
  struct sched_param param;
  int ret;

  param.sched_priority = VS_PRIORITY_AUDIO;
  ret = pthread_attr_setschedparam(attr, &param);
  if (ret == 0)
    {
      ret = pthread_attr_setschedpolicy(attr, SCHED_FIFO);
    }

  if (ret != 0)
    {
      printf("vs_audio: thread priority %d rejected: %d\\n",
             VS_PRIORITY_AUDIO, ret);
    }
}

static uint64_t vs_audio_now_ms(void)"""),
])

