#!/usr/bin/env python3
"""Startup optimizations 1 + 4 + the NAND I/O behind 2/3.

Root cause found in config_store.c: it holds NO in-memory copy, so every
claw_config_get re-reads and re-parses the whole config.json off SD-NAND, and
every claw_config_set re-reads then rewrites it.  vs_voice_open() does dozens of
gets (router/asr/tts init) and nine sets (llm_set_all x5 + volc x4), each one a
separate slow SD-NAND transaction -- that is most of the ~14 s it took.

  #4  cache config.json in memory at init; serve gets from memory; on set,
      skip the write when the value is unchanged.  This removes the redundant
      credential writes and collapses the init-time gets.  One change fixes
      both the "redundant write" and the "registration is slow" halves.

  #1  run vs_voice_open() on a background task instead of on the main thread
      before the event loop, so the home screen paints as soon as history is
      loaded rather than after voice/LLM/ASR/TTS are all up.  Pressing 询问
      before it finishes shows a "准备中" hint instead of starting.

  #2/#3  history load did a stat() per record to check the body file exists;
      for 13 chat records that is 13 VFAT lookups.  Drop it -- a missing body
      is caught when the record is actually opened, and one bad body no longer
      fails the whole index load.
"""

import sys

AI = "/home/mi/vela_competition/contest/packages/ai_agent/"
WS = ("/home/mi/vela_competition/contest/"
      "contest2026_264_VelaSightsuixingAIzhinengyanjing/")


def edit(full, pairs):
    src = open(full, encoding="utf-8").read()
    for label, old, new in pairs:
        if src.count(old) != 1:
            sys.exit("%s / %s: %d matches, expected 1"
                     % (full.rsplit("/", 1)[-1], label, src.count(old)))
        src = src.replace(old, new)
    open(full, "w", encoding="utf-8").write(src)
    print("patched", full.rsplit("/", 1)[-1])


