    cJSON *root = load_json();
    cJSON_DeleteItemFromObject(root, key);
    int ret = save_json(root);
    cJSON_Delete(root);
    pthread_mutex_unlock(&s_lock);
    return ret;
}""",
     """int config_del(const char *key)
{
    pthread_mutex_lock(&s_lock);
    cJSON *root = s_cache ? s_cache : load_json();
    cJSON_DeleteItemFromObject(root, key);
    int ret = save_json(root);
    if (root != s_cache) {
